/**
 * Login Page Component
 *
 * Handles user authentication with both regular login form and Google OAuth.
 */
"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Loader2, Eye, EyeOff, Mail, Lock, ArrowRight } from "lucide-react";
import { AppIcon } from "@/shared/components/icons/icon-registry";

import { parseApiErrors } from "@/shared/lib/api/error";
import { signInWithGoogle, openGoogleAuthPopup, fetchCurrentUser } from "@/shared/lib/api/auth";

import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Checkbox } from "@/shared/ui/checkbox";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { useAuth } from "@/features/auth/components/auth-provider";

export default function LoginPage() {
  const router = useRouter();
  const { login, refreshUser } = useAuth();

  // Form state
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  const [googleLoadingText, setGoogleLoadingText] = useState("Continue with Google");
  const [staySignedIn, setStaySignedIn] = useState(false);

  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [generalError, setGeneralError] = useState<string | null>(null);

  // Reset loading states on back navigation (bfcache)
  useEffect(() => {
    const handleResetLoading = (e: PageTransitionEvent) => {
      if (e.persisted) {
        setGoogleLoading(false);
        setGoogleLoadingText("Continue with Google");
        setLoading(false);
      }
    };

    window.addEventListener("pageshow", handleResetLoading);

    return () => {
      window.removeEventListener("pageshow", handleResetLoading);
    };
  }, []);

  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setEmail(e.target.value);
    if (fieldErrors.email) setFieldErrors((prev) => ({ ...prev, email: "" }));
    if (generalError) setGeneralError(null);
  };

  const handlePasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPassword(e.target.value);
    if (fieldErrors.password) setFieldErrors((prev) => ({ ...prev, password: "" }));
    if (generalError) setGeneralError(null);
  };

  /**
   * Synchronous click handler — opens the popup immediately in the user-gesture
   * call stack, then fires the async OAuth flow without holding the gesture context.
   */
  const handleGoogleLogin = () => {
    const popup = openGoogleAuthPopup();

    if (!popup) {
      toast.error("Google sign-in popup was blocked. Please allow popups for ClixProCRM and try again.");
      return;
    }

    setGoogleLoading(true);
    setGoogleLoadingText("Connecting to Google...");
    void startGoogleOAuth(popup);
  };

  const startGoogleOAuth = async (popup: Window) => {
    try {
      setGoogleLoading(true);
      setGoogleLoadingText("Connecting to Google...");
      const result = await signInWithGoogle(popup);
      if (result?.success && !result?.redirected) {
        setGoogleLoadingText("Signing in...");
        if (typeof window !== "undefined") {
          localStorage.setItem("has_session", "1");
        }
        await refreshUser();
        try {
          const user = await fetchCurrentUser();
          if (user) {
            setGoogleLoadingText("Opening dashboard...");
            const isSuperAdmin =
              user.role?.toUpperCase() === "SUPER_ADMIN" ||
              user.role?.toUpperCase() === "SUPER ADMIN" ||
              (user as any)?.isSuperAdmin === true;
            if (isSuperAdmin) {
              router.replace("/super-admin");
            } else {
              router.replace("/dashboard");
            }
          } else {
            router.replace("/login");
            setGoogleLoading(false);
          }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (err: any) {
          if (err?.message === "NEEDS_ONBOARDING") {
            setGoogleLoadingText("Opening onboarding...");
            router.replace("/onboarding");
          } else {
            setGoogleLoading(false);
            throw err;
          }
        }
      } else {
        setGoogleLoading(false);
      }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      setGoogleLoading(false);
      if (error?.message === "Google sign-in was cancelled.") {
        toast.info("Google sign-in was cancelled.");
      } else {
        toast.error(error.message || "Unable to sign in with Google.");
      }
    }
  };

  /**
   * Handles regular user login
   */
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setLoading(true);
      setFieldErrors({});
      setGeneralError(null);
      const loggedUser = await login(email, password, staySignedIn);

      const isSuperAdmin =
        loggedUser?.role?.toUpperCase() === "SUPER_ADMIN" ||
        loggedUser?.role?.toUpperCase() === "SUPER ADMIN" ||
        (loggedUser as any)?.isSuperAdmin === true;

      const targetRoute = isSuperAdmin ? "/super-admin" : "/dashboard";
      router.replace(targetRoute);
    } catch (error: any) {
      const { fieldErrors, generalError } = parseApiErrors(error, "Login failed");
      setFieldErrors(fieldErrors);
      setGeneralError(generalError);

      setTimeout(() => {
        const firstErrorField = Object.keys(fieldErrors)[0];
        if (firstErrorField) {
          const el = document.getElementById(firstErrorField);
          if (el) el.focus();
        }
      }, 0);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div className="auth-card-header">
        <h2 className="auth-card-title">Welcome Back</h2>
        <p className="auth-card-subtitle">Sign in to access your account</p>
      </div>

      <form onSubmit={handleLogin} className="space-y-4">
        {/* Email */}
        <div className="space-y-1.5">
          <Label htmlFor="email" className="text-xs font-semibold text-foreground/80">
            Email Address
          </Label>
          <div className="relative">
            <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
              <AppIcon name="mail" icon={Mail} size={16} />
            </div>
            <Input
              id="email"
              data-testid="email-input"
              type="email"
              placeholder="name@company.com"
              className={`pl-10 h-11 rounded-xl bg-background/60 transition-all duration-200 border-border/80 focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary ${
                fieldErrors.email ? "border-destructive focus-visible:ring-destructive/20" : ""
              }`}
              value={email}
              onChange={handleEmailChange}
              required
            />
          </div>
          {fieldErrors.email && (
            <p className="text-xs font-medium text-destructive mt-1">{fieldErrors.email}</p>
          )}
        </div>

        {/* Password */}
        <div className="space-y-1.5">
          <div className="flex justify-between items-center">
            <Label htmlFor="password" className="text-xs font-semibold text-foreground/80">
              Password
            </Label>
            <Link
              href="/forgot-password"
              prefetch
              className="text-xs font-medium text-primary hover:text-primary/80 transition-colors"
            >
              Forgot Password?
            </Link>
          </div>
          <div className="relative">
            <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
              <AppIcon name="lock" icon={Lock} size={16} />
            </div>
            <Input
              id="password"
              data-testid="password-input"
              type={showPassword ? "text" : "password"}
              placeholder="Enter your password"
              className={`pl-10 pr-10 h-11 rounded-xl bg-background/60 transition-all duration-200 border-border/80 focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary ${
                fieldErrors.password ? "border-destructive focus-visible:ring-destructive/20" : ""
              }`}
              value={password}
              onChange={handlePasswordChange}
              required
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors p-1 rounded-md"
            >
              {showPassword ? (
                <AppIcon name="eyeOff" icon={EyeOff} size={16} />
              ) : (
                <AppIcon name="eye" icon={Eye} size={16} />
              )}
            </button>
          </div>
          {fieldErrors.password && (
            <p className="text-xs font-medium text-destructive mt-1">{fieldErrors.password}</p>
          )}
          {generalError && !fieldErrors.password && (
            <p className="text-xs font-medium text-destructive mt-1">{generalError}</p>
          )}
        </div>

        {/* Remember */}
        <div className="flex items-center space-x-2 pt-1 pb-1">
          <Checkbox 
            id="remember" 
            checked={staySignedIn}
            onCheckedChange={(checked) => setStaySignedIn(checked === true)}
            disabled={loading}
            className="data-[state=checked]:bg-primary data-[state=checked]:border-primary"
          />
          <Label
            htmlFor="remember"
            className="font-normal text-muted-foreground text-xs cursor-pointer select-none"
          >
            Remember me
          </Label>
        </div>

        {/* Submit */}
        <Button
          type="submit"
          data-testid="login-btn"
          disabled={loading || googleLoading}
          className="w-full h-11 rounded-xl font-semibold shadow-md shadow-primary/20 hover:shadow-lg hover:shadow-primary/30 transition-all duration-200 active:scale-[0.99] flex items-center justify-center gap-2"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>Signing In...</span>
            </>
          ) : (
            <>
              <span>Sign In</span>
              <AppIcon name="arrowRight" icon={ArrowRight} size={16} />
            </>
          )}
        </Button>

        {/* Divider */}
        <div className="relative my-4">
          <div className="absolute inset-0 flex items-center">
            <span className="w-full border-t border-border/80" />
          </div>
          <div className="relative flex justify-center text-[11px] uppercase tracking-wider font-semibold">
            <span className="bg-card px-3 text-muted-foreground">Or continue with</span>
          </div>
        </div>

        {/* Google Login */}
        <Button
          type="button"
          variant="outline"
          disabled={loading || googleLoading}
          onClick={handleGoogleLogin}
          className="w-full h-11 rounded-xl flex items-center justify-center gap-2.5 font-medium border-border hover:bg-muted/40 transition-all duration-200 shadow-sm"
        >
          {googleLoading ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M22.56 12.25C22.56 11.47 22.49 10.72 22.36 10H12V14.26H17.92C17.66 15.63 16.88 16.8 15.71 17.58V20.34H19.28C21.36 18.42 22.56 15.6 22.56 12.25Z" fill="#4285F4" />
              <path d="M12 23C14.97 23 17.46 22.02 19.28 20.34L15.71 17.58C14.73 18.24 13.47 18.66 12 18.66C9.16 18.66 6.75 16.74 5.88 14.18H2.21V17.03C4.01 20.61 7.7 23 12 23Z" fill="#34A853" />
              <path d="M5.88 14.18C5.66 13.52 5.53 12.78 5.53 12C5.53 11.22 5.66 10.48 5.88 9.82V6.97H2.21C1.46 8.46 1 10.18 1 12C1 13.82 1.46 15.54 2.21 17.03L5.88 14.18Z" fill="#FBBC05" />
              <path d="M12 5.34C13.62 5.34 15.06 5.89 16.2 6.98L19.36 3.82C17.45 2.03 14.96 1 12 1C7.7 1 4.01 3.39 2.21 6.97L5.88 9.82C6.75 7.26 9.16 5.34 12 5.34Z" fill="#EA4335" />
            </svg>
          )}
          <span className="text-foreground text-sm font-medium">
            {googleLoading ? googleLoadingText : "Continue with Google"}
          </span>
        </Button>
      </form>

      <p className="auth-card-footer-text">
        Don&apos;t have an account?{" "}
        <Link href="/register" prefetch className="auth-card-footer-link">
          Create Account
        </Link>
      </p>
    </>
  );
}

"use client";

import { useState, useRef } from "react";
import { Loader2, ArrowRight, UploadCloud, ImagePlus, X, Sparkles, Crop } from "lucide-react";
import { AppIcon } from "@/shared/components/icons/icon-registry";
import { useQueryClient } from "@tanstack/react-query";
import { useRouter } from "next/navigation";

import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import client from "@/shared/lib/api/client";
import { useAuth } from "@/features/auth/components/auth-provider";
import { fetchDashboardData } from "@/shared/lib/api/crm";
import { extractErrorMessage } from "@/shared/lib/api/error";
import { extractDominantColorClient } from "@/shared/lib/utils/color-utils";
import { ImageCropperModal } from "@/shared/components/ImageCropperModal";
import { toast } from "sonner";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

export default function OnboardingPage() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { refreshUser } = useAuth();

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [companyName, setCompanyName] = useState("");
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [detectedColor, setDetectedColor] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [cropModalOpen, setCropModalOpen] = useState(false);
  const [selectedRawFile, setSelectedRawFile] = useState<File | null>(null);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSelectRawFile = (file: File) => {
    if (!file.type.startsWith("image/")) {
      toast.error("Please select a valid image file (PNG, JPG, or WebP)");
      return;
    }

    if (file.size > MAX_FILE_SIZE) {
      toast.error("Image file size must be less than 5MB");
      return;
    }

    setSelectedRawFile(file);
    setCropModalOpen(true);
  };

  const handleCropComplete = async (croppedFile: File, previewUrl: string) => {
    setLogoFile(croppedFile);
    if (logoPreview) {
      URL.revokeObjectURL(logoPreview);
    }
    setLogoPreview(previewUrl);

    // Instant client-side color extraction for interactive delight
    try {
      const hex = await extractDominantColorClient(croppedFile);
      setDetectedColor(hex);
    } catch {
      setDetectedColor(null);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      handleSelectRawFile(file);
    }
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) {
      handleSelectRawFile(file);
    }
  };

  const handleOpenCropForCurrentLogo = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!logoFile && !logoPreview) return;
    setSelectedRawFile(logoFile);
    setCropModalOpen(true);
  };

  const handleRemoveLogo = () => {
    setLogoFile(null);
    if (logoPreview) {
      URL.revokeObjectURL(logoPreview);
    }
    setLogoPreview(null);
    setDetectedColor(null);
  };

  const handleOnboarding = async (e: React.FormEvent) => {
    e.preventDefault();
    if (loading) return;

    setError(null);

    const trimmedCompany = companyName.trim();
    if (!trimmedCompany) {
      setError("Company Name is required");
      return;
    }

    setLoading(true);

    try {
      let response;

      if (logoFile) {
        // Read as base64 to ensure seamless multipart/json transmission
        const base64Data = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.onerror = reject;
          reader.readAsDataURL(logoFile);
        });

        response = await client.post("/auth/onboarding", {
          companyName: trimmedCompany,
          logoData: base64Data,
          logoFilename: logoFile.name,
        });
      } else {
        response = await client.post("/auth/onboarding", {
          companyName: trimmedCompany,
        });
      }

      if (!response.data?.success) {
        throw new Error(extractErrorMessage(response.data, "Failed to create workspace"));
      }

      // Hydrate session & auth context
      if (typeof window !== "undefined") {
        localStorage.setItem("has_session", "1");
        sessionStorage.setItem("workspace_activation_celebration_pending", "1");
      }

      await refreshUser();

      // Warm dashboard query cache
      try {
        await queryClient.prefetchQuery({
          queryKey: ["dashboardData", "month"],
          queryFn: () => fetchDashboardData("month"),
          staleTime: 2 * 60 * 1000,
        });
      } catch {
        // Prefetch optimization
      }

      router.push("/dashboard");
    } catch (err: any) {
      const msg = extractErrorMessage(
        err.response?.data,
        err.message || "Something went wrong creating your workspace. Please try again."
      );
      setError(msg);
      setLoading(false);
    }
  };

  return (
    <>
      <div className="auth-card-header">
        <h2 className="auth-card-title">Create Your Workspace 🚀</h2>
        <p className="auth-card-subtitle">
          Set up your company identity and brand styling in seconds.
        </p>
      </div>

      <form onSubmit={handleOnboarding} className="space-y-5">
        {/* Company Name */}
        <div className="space-y-2">
          <Label htmlFor="companyName" className="text-sm font-semibold">
            Company / Workspace Name <span className="text-destructive">*</span>
          </Label>
          <Input
            id="companyName"
            type="text"
            placeholder="Enter company or workspace name"
            className={`rounded-xl h-11 transition-all ${
              error ? "border-destructive focus-visible:ring-destructive" : ""
            }`}
            value={companyName}
            onChange={(e) => {
              setCompanyName(e.target.value);
              if (error) setError(null);
            }}
            required
            disabled={loading}
            autoFocus
          />
          {error && (
            <p className="text-xs text-destructive font-medium mt-1.5 flex items-center gap-1">
              {error}
            </p>
          )}
        </div>

        {/* Company Logo Upload */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <Label className="text-sm font-semibold">
              Company Logo <span className="text-xs font-normal text-muted-foreground">(Optional)</span>
            </Label>
            {detectedColor && (
              <div className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground animate-fadeIn">
                <AppIcon name="ai" icon={Sparkles} size={14} className="text-primary" />
                <span>Detected Color:</span>
                <span
                  className="inline-block w-3.5 h-3.5 rounded-full border border-black/10 shadow-sm"
                  style={{ backgroundColor: detectedColor }}
                />
                <span className="font-mono text-[11px] font-semibold text-foreground uppercase">
                  {detectedColor}
                </span>
              </div>
            )}
          </div>

          <input
            ref={fileInputRef}
            type="file"
            accept="image/png,image/jpeg,image/jpg,image/webp"
            className="hidden"
            onChange={handleFileChange}
            disabled={loading}
          />

          {logoPreview ? (
            <div className="relative rounded-2xl border-2 border-border/80 p-3 bg-card/60 flex items-center gap-4 transition-all">
              <div className="w-16 h-16 rounded-xl border border-border/60 bg-muted/30 flex items-center justify-center p-2 overflow-hidden shrink-0">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={logoPreview}
                  alt="Company Logo Preview"
                  className="w-full h-full object-contain"
                />
              </div>

              <div className="flex-1 min-w-0">
                <p className="text-xs font-bold text-foreground truncate">
                  {logoFile?.name || "logo.png"}
                </p>
                <p className="text-[11px] text-muted-foreground mt-0.5">
                  {logoFile ? `${(logoFile.size / 1024).toFixed(1)} KB` : "Selected"} • Dominant brand color will be extracted
                </p>
                <div className="flex items-center gap-2 mt-1.5">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="h-7 text-[11px] px-2.5 rounded-lg"
                    onClick={() => fileInputRef.current?.click()}
                    disabled={loading}
                  >
                    <AppIcon name="upload" icon={ImagePlus} size={12} className="mr-1 text-primary" />
                    Change
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="h-7 text-[11px] px-2.5 rounded-lg"
                    onClick={handleOpenCropForCurrentLogo}
                    disabled={loading}
                  >
                    <AppIcon name="edit" icon={Crop} size={12} className="mr-1 text-primary" />
                    Crop
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="h-7 text-[11px] px-2 rounded-lg text-rose-500 hover:text-rose-600 hover:bg-rose-500/10"
                    onClick={handleRemoveLogo}
                    disabled={loading}
                  >
                    <AppIcon name="close" icon={X} size={12} className="mr-1" />
                    Remove
                  </Button>
                </div>
              </div>
            </div>
          ) : (
            <div
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
              className={`border-2 border-dashed rounded-2xl p-4 text-center cursor-pointer transition-all flex flex-col items-center justify-center gap-2 bg-muted/20 hover:bg-muted/40 ${
                isDragging
                  ? "border-primary bg-primary/10 ring-4 ring-primary/20 scale-[1.01]"
                  : "border-border/80 hover:border-primary/60"
              }`}
            >
              <div className="w-10 h-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center transition-transform group-hover:scale-110">
                <AppIcon name="upload" icon={UploadCloud} size={20} />
              </div>
              <div>
                <p className="text-xs font-semibold text-foreground">
                  Click to upload or drag and drop
                </p>
                <p className="text-[11px] text-muted-foreground mt-0.5">
                  PNG, JPG, or WebP (max. 5MB)
                </p>
              </div>
            </div>
          )}

          {/* Image Cropper Modal */}
          <ImageCropperModal
            open={cropModalOpen}
            onOpenChange={setCropModalOpen}
            imageFile={selectedRawFile}
            imageSrc={logoPreview}
            onCropComplete={handleCropComplete}
            title="Crop Company Logo"
            description="Adjust framing, zoom and aspect ratio to ensure your company logo looks sharp."
          />
        </div>

        {/* Submit Action */}
        <Button
          type="submit"
          disabled={loading}
          className="rounded-xl w-full h-11 flex items-center justify-center gap-2 font-semibold shadow-md transition-all cursor-pointer disabled:cursor-not-allowed"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>Setting up your workspace & brand...</span>
            </>
          ) : (
            <>
              <span>Create Workspace</span>
              <AppIcon name="arrowRight" icon={ArrowRight} size={16} />
            </>
          )}
        </Button>
      </form>
    </>
  );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Loader2, Eye, EyeOff, User, Building2, Mail, Lock, ArrowRight } from "lucide-react";
import { AppIcon } from "@/shared/components/icons/icon-registry";

import { registerUser, signInWithGoogle, openGoogleAuthPopup, fetchCurrentUser } from "@/shared/lib/api/auth";
import { parseApiErrors } from "@/shared/lib/api/error";

import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { useAuth } from "@/features/auth/components/auth-provider";

export default function RegisterPage() {
  const router = useRouter();
  const { refreshUser } = useAuth();

  // Form state
  const [name, setName] = useState("");
  const [companyName, setCompanyName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // Loading
  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  const [googleLoadingText, setGoogleLoadingText] = useState("Continue with Google");

  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [generalError, setGeneralError] = useState<string | null>(null);

  // Reset loading states on back navigation (bfcache)
  useEffect(() => {
    const handleResetLoading = (e: PageTransitionEvent) => {
      if (e.persisted) {
        setGoogleLoading(false);
        setGoogleLoadingText("Continue with Google");
        setLoading(false);
      }
    };

    window.addEventListener("pageshow", handleResetLoading);

    return () => {
      window.removeEventListener("pageshow", handleResetLoading);
    };
  }, []);

  const clearFieldError = (fieldName: string) => {
    if (fieldErrors[fieldName]) {
      setFieldErrors((prev) => {
        const next = { ...prev };
        delete next[fieldName];
        return next;
      });
    }
    if (generalError) setGeneralError(null);
  };

  /**
   * Synchronous click handler — opens popup immediately in the user gesture call stack
   */
  const handleGoogleLogin = () => {
    const popup = openGoogleAuthPopup();

    if (!popup) {
      toast.error("Google sign-in popup was blocked. Please allow popups for ClixProCRM and try again.");
      return;
    }

    setGoogleLoading(true);
    setGoogleLoadingText("Connecting to Google...");
    void startGoogleOAuth(popup);
  };

  const startGoogleOAuth = async (popup: Window) => {
    try {
      setGoogleLoading(true);
      setGoogleLoadingText("Connecting to Google...");
      const result = await signInWithGoogle(popup);
      if (result?.success && !result?.redirected) {
        setGoogleLoadingText("Signing in...");
        if (typeof window !== "undefined") {
          localStorage.setItem("has_session", "1");
        }
        await refreshUser();
        try {
          const user = await fetchCurrentUser();
          if (user) {
            setGoogleLoadingText("Opening dashboard...");
            const isSuperAdmin =
              user.role?.toUpperCase() === "SUPER_ADMIN" ||
              user.role?.toUpperCase() === "SUPER ADMIN" ||
              (user as any)?.isSuperAdmin === true;
            if (isSuperAdmin) {
              router.replace("/super-admin");
            } else {
              router.replace("/dashboard");
            }
          } else {
            router.replace("/login");
            setGoogleLoading(false);
          }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (err: any) {
          if (err?.message === "NEEDS_ONBOARDING") {
            setGoogleLoadingText("Opening onboarding...");
            router.replace("/onboarding");
          } else {
            setGoogleLoading(false);
            throw err;
          }
        }
      } else {
        setGoogleLoading(false);
      }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      setGoogleLoading(false);
      if (error?.message === "Google sign-in was cancelled.") {
        toast.info("Google sign-in was cancelled.");
      } else {
        toast.error(error.message || "Unable to sign in with Google.");
      }
    }
  };

  /**
   * Handles user registration
   */
  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();

    if (password !== confirmPassword) {
      setFieldErrors((prev) => ({
        ...prev,
        confirmPassword: "Passwords do not match",
      }));
      return;
    }

    try {
      setLoading(true);
      setFieldErrors({});
      setGeneralError(null);

      await registerUser({
        name,
        companyName,
        email,
        password,
      });

      toast.success("Account created successfully!");
      // Automatic login or onboarding redirect handled by auth state
      await refreshUser();
      router.push("/onboarding");
    } catch (error: unknown) {
      const { fieldErrors, generalError } = parseApiErrors(error, "Registration failed");
      setFieldErrors(fieldErrors);
      setGeneralError(generalError);

      setTimeout(() => {
        const firstErrorField = Object.keys(fieldErrors)[0];
        if (firstErrorField) {
          const el = document.getElementById(firstErrorField);
          if (el) el.focus();
        }
      }, 0);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div className="auth-card-header mb-5">
        <h2 className="auth-card-title">Create Account</h2>
        <p className="auth-card-subtitle">Start managing your sales today</p>
      </div>

      <form onSubmit={handleRegister} className="space-y-3.5">
        {/* Row 1: Full Name & Company Name (2 Columns) */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {/* Name */}
          <div className="space-y-1.5">
            <Label htmlFor="name" className="text-xs font-semibold text-foreground/80">
              Full Name
            </Label>
            <div className="relative">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
                <AppIcon name="user" icon={User} size={16} />
              </div>
              <Input
                id="name"
                type="text"
                placeholder="John Doe"
                className={`pl-9.5 h-10 rounded-xl bg-background/60 text-sm transition-all duration-200 border-border/80 focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary ${
                  fieldErrors.name ? "border-destructive focus-visible:ring-destructive/20" : ""
                }`}
                value={name}
                onChange={(e) => { setName(e.target.value); clearFieldError("name"); }}
                required
              />
            </div>
            {fieldErrors.name && (
              <p className="text-xs font-medium text-destructive mt-1">{fieldErrors.name}</p>
            )}
          </div>

          {/* Company Name */}
          <div className="space-y-1.5">
            <Label htmlFor="companyName" className="text-xs font-semibold text-foreground/80">
              Company Name
            </Label>
            <div className="relative">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
                <AppIcon name="companies" icon={Building2} size={16} />
              </div>
              <Input
                id="companyName"
                type="text"
                placeholder="Acme Corp"
                className={`pl-9.5 h-10 rounded-xl bg-background/60 text-sm transition-all duration-200 border-border/80 focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary ${
                  fieldErrors.companyName ? "border-destructive focus-visible:ring-destructive/20" : ""
                }`}
                value={companyName}
                onChange={(e) => { setCompanyName(e.target.value); clearFieldError("companyName"); }}
                required
              />
            </div>
            {fieldErrors.companyName && (
              <p className="text-xs font-medium text-destructive mt-1">{fieldErrors.companyName}</p>
            )}
          </div>
        </div>

        {/* Row 2: Email Address (Full Width) */}
        <div className="space-y-1.5">
          <Label htmlFor="email" className="text-xs font-semibold text-foreground/80">
            Email Address
          </Label>
          <div className="relative">
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
              <AppIcon name="mail" icon={Mail} size={16} />
            </div>
            <Input
              id="email"
              type="email"
              placeholder="name@company.com"
              className={`pl-9.5 h-10 rounded-xl bg-background/60 text-sm transition-all duration-200 border-border/80 focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary ${
                fieldErrors.email ? "border-destructive focus-visible:ring-destructive/20" : ""
              }`}
              value={email}
              onChange={(e) => { setEmail(e.target.value); clearFieldError("email"); }}
              required
            />
          </div>
          {fieldErrors.email && (
            <p className="text-xs font-medium text-destructive mt-1">{fieldErrors.email}</p>
          )}
        </div>

        {/* Row 3: Password & Confirm Password (2 Columns) */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {/* Password */}
          <div className="space-y-1.5">
            <Label htmlFor="password" className="text-xs font-semibold text-foreground/80">
              Password
            </Label>
            <div className="relative">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
                <AppIcon name="lock" icon={Lock} size={16} />
              </div>
              <Input
                id="password"
                type={showPassword ? "text" : "password"}
                placeholder="Min. 6 chars"
                className={`pl-9.5 pr-9 h-10 rounded-xl bg-background/60 text-sm transition-all duration-200 border-border/80 focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary ${
                  fieldErrors.password ? "border-destructive focus-visible:ring-destructive/20" : ""
                }`}
                value={password}
                onChange={(e) => { setPassword(e.target.value); clearFieldError("password"); }}
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors p-1 rounded-md"
              >
                {showPassword ? (
                  <AppIcon name="eyeOff" icon={EyeOff} size={15} />
                ) : (
                  <AppIcon name="eye" icon={Eye} size={15} />
                )}
              </button>
            </div>
            {fieldErrors.password && (
              <p className="text-xs font-medium text-destructive mt-1">{fieldErrors.password}</p>
            )}
          </div>

          {/* Confirm Password */}
          <div className="space-y-1.5">
            <Label htmlFor="confirmPassword" className="text-xs font-semibold text-foreground/80">
              Confirm Password
            </Label>
            <div className="relative">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">
                <AppIcon name="lock" icon={Lock} size={16} />
              </div>
              <Input
                id="confirmPassword"
                type={showConfirmPassword ? "text" : "password"}
                placeholder="Confirm password"
                className={`pl-9.5 pr-9 h-10 rounded-xl bg-background/60 text-sm transition-all duration-200 border-border/80 focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary ${
                  fieldErrors.confirmPassword ? "border-destructive focus-visible:ring-destructive/20" : ""
                }`}
                value={confirmPassword}
                onChange={(e) => { setConfirmPassword(e.target.value); clearFieldError("confirmPassword"); }}
                required
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors p-1 rounded-md"
              >
                {showConfirmPassword ? (
                  <AppIcon name="eyeOff" icon={EyeOff} size={15} />
                ) : (
                  <AppIcon name="eye" icon={Eye} size={15} />
                )}
              </button>
            </div>
            {fieldErrors.confirmPassword && (
              <p className="text-xs font-medium text-destructive mt-1">{fieldErrors.confirmPassword}</p>
            )}
          </div>
        </div>

        {generalError && !fieldErrors.confirmPassword && !fieldErrors.password && (
          <p className="text-xs font-medium text-destructive mt-1">{generalError}</p>
        )}

        {/* Submit */}
        <Button
          type="submit"
          disabled={loading || googleLoading}
          className="w-full h-10.5 rounded-xl font-semibold shadow-md shadow-primary/20 hover:shadow-lg hover:shadow-primary/30 transition-all duration-200 active:scale-[0.99] flex items-center justify-center gap-2 mt-2"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>Creating Account...</span>
            </>
          ) : (
            <>
              <span>Create Account</span>
              <AppIcon name="arrowRight" icon={ArrowRight} size={16} />
            </>
          )}
        </Button>

        {/* Divider */}
        <div className="relative my-2.5">
          <div className="absolute inset-0 flex items-center">
            <span className="w-full border-t border-border/80" />
          </div>
          <div className="relative flex justify-center text-[11px] uppercase tracking-wider font-semibold">
            <span className="bg-card px-3 text-muted-foreground">Or continue with</span>
          </div>
        </div>

        {/* Google Button */}
        <Button
          type="button"
          variant="outline"
          disabled={loading || googleLoading}
          onClick={handleGoogleLogin}
          className="w-full h-10.5 rounded-xl flex items-center justify-center gap-2.5 font-medium border-border hover:bg-muted/40 transition-all duration-200 shadow-sm"
        >
          {googleLoading ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M22.56 12.25C22.56 11.47 22.49 10.72 22.36 10H12V14.26H17.92C17.66 15.63 16.88 16.8 15.71 17.58V20.34H19.28C21.36 18.42 22.56 15.6 22.56 12.25Z" fill="#4285F4" />
              <path d="M12 23C14.97 23 17.46 22.02 19.28 20.34L15.71 17.58C14.73 18.24 13.47 18.66 12 18.66C9.16 18.66 6.75 16.74 5.88 14.18H2.21V17.03C4.01 20.61 7.7 23 12 23Z" fill="#34A853" />
              <path d="M5.88 14.18C5.66 13.52 5.53 12.78 5.53 12C5.53 11.22 5.66 10.48 5.88 9.82V6.97H2.21C1.46 8.46 1 10.18 1 12C1 13.82 1.46 15.54 2.21 17.03L5.88 14.18Z" fill="#FBBC05" />
              <path d="M12 5.34C13.62 5.34 15.06 5.89 16.2 6.98L19.36 3.82C17.45 2.03 14.96 1 12 1C7.7 1 4.01 3.39 2.21 6.97L5.88 9.82C6.75 7.26 9.16 5.34 12 5.34Z" fill="#EA4335" />
            </svg>
          )}
          <span className="text-foreground text-sm font-medium">
            {googleLoading ? googleLoadingText : "Continue with Google"}
          </span>
        </Button>
      </form>

      <p className="auth-card-footer-text !mt-4 !pt-3">
        Already have an account?{" "}
        <Link href="/login" prefetch className="auth-card-footer-link">
          Sign In
        </Link>
      </p>
    </>
  );
}

"use client";

import { 
  Sparkles, 
  TrendingUp, 
  ArrowRight,
  BrainCircuit,
  MessageSquare,
  BarChart3,
  Lightbulb,
  Settings,
} from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { 
  CRMPageContainer, 
  CRMPageHeader, 
  CRMMetricsGrid, 
  MetricCard, 
  CRMCard,
  ActivityTimeline,
  CRMPageSection
} from "@/shared/components/crm";
import { AIContextualSettings } from "@/features/ai/components/AIContextualSettings";
import { Button } from "@/shared/ui/button";
import { useAiInsights } from "@/shared/hooks/use-dashboard";
import { AISkeleton } from "./AISkeleton";
import { 
  Area, 
  AreaChart, 
  XAxis, 
  YAxis, 
  Tooltip,
  CartesianGrid 
} from "recharts";
// import { } from "framer-";
import { toast } from "sonner";

import { ChartContainer } from "@/shared/components/charts/ChartContainer";

interface AIRecommendation {
  id: string | number;
  title: string;
  description: string;
  bgColor?: string;
  color?: string;
  icon?: React.ElementType;
  priority?: 'high' | 'medium' | 'low';
  tag?: string;
}

interface InsightStat {
  title: string;
  value: string;
  change?: string;
  positive?: boolean;
  color?: string;
  iconName?: string;
}

import { EmptyState } from "@/shared/components/EmptyState";
import { useRouter } from "next/navigation";
import { LayoutDashboard, UserPlus } from "lucide-react";
import React, { useState, useMemo } from "react";

export default function AiInsightsPage() {
  const router = useRouter();
  const { data: insightsData, isLoading: loading } = useAiInsights();
  const [isCustomizeOpen, setIsCustomizeOpen] = useState(false);

  const recommendations = insightsData?.recommendations || [];
  const aiStats = insightsData?.stats || [];
  const aiTimeline = insightsData?.timeline || [];

  const hasAiData = useMemo(() => {
    if (!insightsData) return false;
    const hasRecs = recommendations.length > 0;
    const hasTimeline = aiTimeline.length > 0;
    const hasMeaningfulStats = aiStats.some(s => s.value && s.value !== "0" && s.value !== "0%" && s.value !== "0.0%");
    return Boolean(hasRecs || hasTimeline || hasMeaningfulStats);
  }, [insightsData, recommendations, aiTimeline, aiStats]);

  const handleAskAI = () => {
    toast.success("AI Assistant", {
      description: "How can I help you analyze your business data today?",
    });
  };

  if (loading) {
    return <AISkeleton />;
  }

  if (!hasAiData) {
    return (
      <CRMPageContainer>
        <CRMPageHeader
          title="AI Intelligence Hub"
          subtitle="Harness neural forecasting and intelligent recommendations to scale your business."
          badge="Neural Engine v4.2"
          icon={BrainCircuit}
          iconColor="text-indigo-500"
          actions={[
            {
              label: "Customize",
              icon: Settings,
              onClick: () => setIsCustomizeOpen(true),
              variant: "outline",
            },
          ]}
        />

        <div className="flex-1 min-h-0 flex flex-col">
          <EmptyState
            module="analytics"
            icon={BrainCircuit}
            title="AI Intelligence will activate with your data"
            description="Once you have active leads, customer engagements, and deal milestones recorded, the AI Neural Engine will provide predictive win-rates, lead scoring, and automated growth recommendations."
            action={{
              label: "Go to Dashboard",
              onClick: () => router.push("/dashboard"),
              icon: LayoutDashboard,
            }}
            secondaryAction={{
              label: "Create First Lead",
              onClick: () => router.push("/contacts?status=lead"),
              icon: UserPlus,
            }}
          />
        </div>

        <AIContextualSettings
          open={isCustomizeOpen}
          onOpenChange={setIsCustomizeOpen}
        />
      </CRMPageContainer>
    );
  }

  return (
    <CRMPageContainer>
      <CRMPageHeader
        title="AI Intelligence Hub"
        subtitle="Harness neural forecasting and intelligent recommendations to scale your business."
        badge="Neural Engine v4.2"
        icon={BrainCircuit}
        iconColor="text-indigo-500"
        actions={[
          {
            label: "Customize",
            icon: Settings,
            onClick: () => setIsCustomizeOpen(true),
            variant: "outline",
          },
          {
            label: "Export AI Report",
            icon: BarChart3,
            onClick: () => toast.info("Generating AI Analysis Report..."),
            variant: "outline",
          },
          {
            label: "Ask Assistant",
            icon: MessageSquare,
            onClick: handleAskAI,
            variant: "default",
          },
        ]}
      />

      {/* AI Stats Grid */}
      <CRMMetricsGrid>
        {aiStats.map((stat: InsightStat, i: number) => (
          <MetricCard
            key={i}
            {...stat}
            color={stat.color as "emerald" | "cyan" | "indigo" | "violet" | "orange" | "pink" | "blue" | "purple" | "primary" | "slate" | undefined}
            delay={i * 0.1}
          />
        ))}
      </CRMMetricsGrid>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 min-w-0">
        {/* Main Insights Panel */}
        <div className="lg:col-span-2 space-y-8 min-w-0">
          <CRMPageSection 
            title="Performance Predictions" 
            subtitle="Revenue vs AI Forecast for the next 6 weeks."
            className="min-w-0"
          >
            <CRMCard className="h-[400px] min-h-[400px] p-6 min-w-0">
              <ChartContainer 
                height="100%" 
                hasData={Boolean(insightsData?.forecastData && insightsData.forecastData.length > 0)}
                className="w-full h-full"
              >
                <AreaChart data={insightsData?.forecastData || []}>
                  <defs>
                    <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                    </linearGradient>
                    <linearGradient id="colorPrediction" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(0,0,0,0.05)" />
                  <XAxis 
                    dataKey="name" 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{ fontSize: 10, fontWeight: 600 }}
                    dy={10}
                  />
                  <YAxis 
                    axisLine={false} 
                    tickLine={false} 
                    tick={{ fontSize: 10, fontWeight: 600 }}
                  />
                  <Tooltip 
                    contentStyle={{ 
                      borderRadius: '12px', 
                      border: 'none', 
                      boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' 
                    }} 
                  />
                  <Area 
                    type="monotone" 
                    dataKey="revenue" 
                    stroke="#6366f1" 
                    strokeWidth={3}
                    fillOpacity={1} 
                    fill="url(#colorRevenue)" 
                  />
                  <Area 
                    type="monotone" 
                    dataKey="prediction" 
                    stroke="#10b981" 
                    strokeWidth={3}
                    strokeDasharray="5 5"
                    fillOpacity={1} 
                    fill="url(#colorPrediction)" 
                  />
                </AreaChart>
              </ChartContainer>
            </CRMCard>
          </CRMPageSection>

          <CRMPageSection 
            title="Smart Recommendations" 
            subtitle="AI-generated actions to optimize your sales funnel."
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {recommendations.map((rec: AIRecommendation) => (
                <CRMCard 
                  key={rec.id} 
                  className="p-5 flex flex-col justify-between"
                  accentSeed={rec.title}
                >
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <div className={cn("p-2 rounded-lg", rec.bgColor, rec.color)}>
                        {/* Fallback for icon if it's a component or just use Sparkles as default */}
                        {typeof rec.icon === 'function' ? <rec.icon className="w-4 h-4" /> : <Sparkles className="w-4 h-4" />}
                      </div>
                      <span className={cn(
                        "px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider",
                        rec.priority === 'high' ? 'bg-rose-500/10 text-rose-500' : 
                        rec.priority === 'medium' ? 'bg-orange-500/10 text-orange-500' : 'bg-emerald-500/10 text-emerald-500'
                      )}>
                        {rec.tag}
                      </span>
                    </div>
                    <div>
                      <h4 className="text-sm font-bold tracking-tight mb-1">{rec.title}</h4>
                      <p className="text-xs text-muted-foreground leading-relaxed">
                        {rec.description}
                      </p>
                    </div>
                  </div>
                  <Button variant="ghost" size="sm" className="w-full mt-4 justify-between group h-9">
                    Take Action
                    <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-1 transition-transform" />
                  </Button>
                </CRMCard>
              ))}

              {/* AI Assistant Widget Card */}
              <CRMCard className="p-5 bg-indigo-500/[0.03] border-indigo-500/20 flex flex-col items-center justify-center text-center space-y-4">
                <div className="p-3 bg-indigo-500 rounded-xl shadow-lg shadow-indigo-500/20">
                  <Sparkles className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h4 className="text-sm font-bold tracking-tight mb-1">Need deeper insights?</h4>
                  <p className="text-[11px] text-muted-foreground px-4">
                    Ask our AI assistant any question about your data.
                  </p>
                </div>
                <Button 
                  onClick={handleAskAI}
