            variant="destructive"
            onClick={onConfirmDelete}
            disabled={
              isPending || (assignedCount > 0 && !replacementRoleId)
            }
          >
            {isPending
              ? "Deleting..."
              : assignedCount > 0
                ? "Reassign & Delete"
                : "Delete Role"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

