"use client";

import React, { useState, useMemo } from "react";
import {
  Shield,
  ShieldCheck,
  Users,
  Plus,
} from "lucide-react";
import {
  CRMMetricsGrid,
  CRMMetricCard,
  CRMToolbar,
  DataTable,
  CRMTableHeader,
  CRMTableBody,
  CRMTableRow,
  CRMTableHeaderCell,
  CRMPagination,
} from "@/shared/components/crm";
import { Button } from "@/shared/ui/button";
import { toast } from "sonner";
import { RoleManagementSkeleton } from "../RoleManagementSkeleton";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useDebounce } from "@/hooks/use-debounce";
import { useAuth } from "@/features/auth/components/auth-provider";
import client from "@/shared/lib/api/client";
import { RoleEditorModal } from "./RoleEditorModal";
import { RoleDetailsDialog } from "./RoleDetailsDialog";
import { RoleDeleteDialog } from "./RoleDeleteDialog";
import { RoleTableRows } from "./RoleTableRows";

interface RolePermission {
  module: string;
  hasAccess: boolean;
}

interface Role {
  id: string;
  name: string;
  description?: string | null;
  isSystem: boolean;
  isActive: boolean;
  color?: string | null;
  priority?: number;
  permissions: RolePermission[];
  _count?: { users: number; permissions: number; invitations?: number };
}

const ROLE_SYSTEM_COLORS: Record<string, string> = {
  "SUPER ADMIN": "#6366f1", // Indigo
  ADMIN: "#3b82f6",         // Royal Blue
  MANAGER: "#8b5cf6",       // Violet / Purple
  SALES: "#f59e0b",         // Amber / Orange
  EMPLOYEE: "#10b981",      // Emerald Green
  SUPPORT: "#ec4899",       // Pink
  FINANCE: "#06b6d4",       // Cyan
  MARKETING: "#f43f5e",     // Rose
};

export const getRoleColor = (role?: Role | null): string => {
  if (!role) return "#10b981";
  const upper = (role.name || "").trim().toUpperCase();
  if (role.isSystem && ROLE_SYSTEM_COLORS[upper]) {
    return ROLE_SYSTEM_COLORS[upper];
  }
  if (role.color && role.color !== "#10b981") {
    return role.color;
  }
  if (ROLE_SYSTEM_COLORS[upper]) {
    return ROLE_SYSTEM_COLORS[upper];
  }
  const customPalette = [
    "#8b5cf6",
    "#3b82f6",
    "#f59e0b",
    "#10b981",
    "#ec4899",
    "#06b6d4",
    "#f43f5e",
    "#6366f1",
  ];
  let hash = 0;
  for (let i = 0; i < role.name.length; i++) {
    hash = role.name.charCodeAt(i) + ((hash << 5) - hash);
  }
  return customPalette[Math.abs(hash) % customPalette.length];
};

export function RoleList({ onCreateRoleTrigger }: { onCreateRoleTrigger?: () => void }) {
  const queryClient = useQueryClient();
  const { user, isHydrated, isAuthenticated, isInitializing } = useAuth();
  const currentUserRole = (user?.role || "EMPLOYEE").toUpperCase();
  const canManageRoles =
    currentUserRole === "SUPER ADMIN" ||
    currentUserRole === "ADMIN" ||
    currentUserRole === "OWNER";

  // Search State
  const [searchQuery, setSearchQuery] = useState("");
  const debouncedSearch = useDebounce(searchQuery, 300) || "";

  // Modal states
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<Role | null>(null);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [viewingRole, setViewingRole] = useState<Role | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingRole, setDeletingRole] = useState<Role | null>(null);
  const [replacementRoleId, setReplacementRoleId] = useState<string>("");

  // Editor Form State
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    color: "#3b82f6",
    permissions: [] as string[],
  });

  // Queries
  const { data: rolesData, isLoading: isRolesLoading, isPending: isRolesPending } = useQuery<{
    success: boolean;
    data: Role[];
  }>({
    queryKey: ["roles"],
    queryFn: async () => {
      const res = await client.get("/crm/roles");
      return res.data;
    },
  });

  const { data: statsData } = useQuery<{
    success: boolean;
    data: any;
  }>({
    queryKey: ["roles-stats"],
    queryFn: async () => {
      try {
        const res = await client.get("/crm/role-management/stats");
        return res.data;
      } catch {
        return null;
      }
    },
  });

  const roles = Array.isArray(rolesData?.data) ? rolesData.data : [];
  const stats = useMemo(() => {
    const rawStats = statsData?.data;
    if (rawStats) {
      const totalRoles = rawStats.roles?.total ?? rawStats.total ?? roles.length;
      const customRoles = rawStats.roles?.custom ?? rawStats.custom ?? roles.filter((r) => !r.isSystem).length;
      const totalUsers = rawStats.users?.total ?? rawStats.totalAssignedUsers ?? roles.reduce((acc, r) => acc + (r._count?.users || 0), 0);
      return {
        total: totalRoles,
        custom: customRoles,
        totalAssignedUsers: totalUsers,
      };
    }
    return {
      total: roles.length,
      system: roles.filter((r) => r.isSystem).length,
      custom: roles.filter((r) => !r.isSystem).length,
      totalAssignedUsers: roles.reduce(
        (acc, r) => acc + (r._count?.users || 0),
        0,
      ),
    };
  }, [roles, statsData]);

  const isLoading = !rolesData && (isRolesLoading || isRolesPending || !isHydrated || !isAuthenticated || isInitializing);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  // Filter roles by search
  const filteredRoles = useMemo(() => {
    if (!debouncedSearch.trim()) return roles;
    const q = debouncedSearch.toLowerCase();
    return roles.filter(
      (r) =>
        r.name.toLowerCase().includes(q) ||
        (r.description && r.description.toLowerCase().includes(q)),
    );
  }, [roles, debouncedSearch]);

  const totalPages = Math.ceil(filteredRoles.length / rowsPerPage) || 1;
  const paginatedRoles = useMemo(() => {
    return filteredRoles.slice(
      (currentPage - 1) * rowsPerPage,
      currentPage * rowsPerPage
    );
  }, [filteredRoles, currentPage, rowsPerPage]);

  const availableReplacementRoles = useMemo(() => {
    if (!deletingRole) return [];
    return roles.filter((r) => r.id !== deletingRole.id);
  }, [roles, deletingRole]);

  // Check form dirty
  const isFormDirty = useMemo(() => {
    if (!editingRole) return true;
    if (formData.name !== editingRole.name) return true;
    if ((formData.color || "") !== (editingRole.color || "#3b82f6")) return true;
    const initialPerms = (editingRole.permissions || [])
      .filter((p) => p.hasAccess)
      .map((p) => p.module);
    if (formData.permissions.length !== initialPerms.length) return true;
    const currentSet = new Set(formData.permissions);
    return !initialPerms.every((p) => currentSet.has(p));
  }, [formData, editingRole]);

  // Mutations
  const saveRoleMutation = useMutation({
    mutationFn: async ({
      roleId,
      isNew,
      payload,
    }: {
      roleId?: string;
      isNew: boolean;
      payload: any;
    }) => {
      if (isNew) {
        const res = await client.post("/crm/roles", payload);
        return res.data;
      } else {
        const res = await client.put(`/crm/roles/${roleId}`, payload);
        return res.data;
      }
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["roles"] });
      queryClient.invalidateQueries({ queryKey: ["roles-stats"] });
      toast.success(
        variables.isNew
          ? "Role created successfully!"
          : "Role updated successfully!",
      );
      setEditorOpen(false);
      setEditingRole(null);
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || "Failed to save role";
      toast.error(typeof msg === "string" ? msg : JSON.stringify(msg));
    },
  });

  const deleteRoleMutation = useMutation({
    mutationFn: async ({
      roleId,
      replacementId,
    }: {
      roleId: string;
      replacementId?: string;
    }) => {
      const query = replacementId ? `?replacementRoleId=${replacementId}` : "";
      const res = await client.delete(`/crm/roles/${roleId}${query}`);
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["roles"] });
      queryClient.invalidateQueries({ queryKey: ["roles-stats"] });
      toast.success("Role deleted successfully!");
      setDeleteDialogOpen(false);
      setDeletingRole(null);
      setReplacementRoleId("");
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || "Failed to delete role";
      toast.error(typeof msg === "string" ? msg : JSON.stringify(msg));
    },
  });

  // Handlers
  const handleOpenCreate = () => {
    if (onCreateRoleTrigger) {
      onCreateRoleTrigger();
      return;
    }
    setEditingRole(null);
    setFormData({
      name: "",
      description: "",
      color: "#3b82f6",
      permissions: [],
    });
    setEditorOpen(true);
  };

  const handleOpenEdit = (role: Role) => {
    setEditingRole(role);
    const activePerms = (role.permissions || [])
      .filter((p) => p.hasAccess)
      .map((p) => p.module);
    setFormData({
      name: role.name,
      description: role.description || "",
      color: role.color || getRoleColor(role),
      permissions: activePerms,
    });
    setEditorOpen(true);
  };

  const handleOpenView = (role: Role) => {
    setViewingRole(role);
    setViewDialogOpen(true);
  };

  const handleOpenDelete = (role: Role) => {
    setDeletingRole(role);
    setReplacementRoleId("");
    setDeleteDialogOpen(true);
  };

  const handleSaveEditor = () => {
    if (!formData.name.trim()) {
      toast.error("Please enter a role name");
      return;
    }

    const payload = {
      name: formData.name.trim(),
      description: formData.description?.trim() || null,
      color: formData.color,
      permissions: formData.permissions.map((module) => ({
        module,
        hasAccess: true,
      })),
    };

    saveRoleMutation.mutate({
      roleId: editingRole?.id,
      isNew: !editingRole,
      payload,
    });
  };

  const handleDeleteConfirm = () => {
    if (!deletingRole) return;
    deleteRoleMutation.mutate({
      roleId: deletingRole.id,
      replacementId: replacementRoleId || undefined,
    });
  };

  if (isLoading) return <RoleManagementSkeleton />;

  return (
    <div className="flex-1 flex flex-col min-h-0 gap-3.5 sm:gap-4">
      {/* ── Standard CRMMetricsGrid matching Contacts & Employees ── */}
      <div className="shrink-0">
        <CRMMetricsGrid cols={3}>
          <CRMMetricCard
            title="Total Roles"
            value={stats.total}
            change="0%"
            trend="up"
            icon={Shield}
            color="indigo"
            delay={0.1}
          />
          <CRMMetricCard
            title="Custom Roles"
            value={stats.custom}
            change="Custom"
            trend="up"
            icon={ShieldCheck}
            color="emerald"
            delay={0.2}
          />
          <CRMMetricCard
            title="Assigned Users"
            value={stats.totalAssignedUsers}
            change="Members"
            trend="up"
            icon={Users}
            color="orange"
            delay={0.3}
          />
        </CRMMetricsGrid>
      </div>

      {/* ── Two-Stage Scroll Workspace ── */}
      <div className="crm-table-workspace-sticky">
        {/* ── Standard CRMToolbar with Search & Action ── */}
        <CRMToolbar
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          placeholder="Search roles by name or description..."
          sticky={false}
        >
          {canManageRoles && (
            <Button
              onClick={handleOpenCreate}
              size="sm"
              className="h-9 gap-1.5 text-xs font-semibold"
            >
              <Plus className="h-4 w-4" />
              Create Role
            </Button>
          )}
        </CRMToolbar>

        {/* ── Standard DataTable ── */}
        <div className="flex-1 min-h-0 flex flex-col">
          <DataTable hasPagination={filteredRoles.length > rowsPerPage}>
            <CRMTableHeader>
              <CRMTableRow>
                <CRMTableHeaderCell className="w-[32%]">Role Name</CRMTableHeaderCell>
                <CRMTableHeaderCell className="w-[18%]">Assigned Users</CRMTableHeaderCell>
                <CRMTableHeaderCell className="w-[45%]">Permission Modules</CRMTableHeaderCell>
                <CRMTableHeaderCell className="w-[5%] text-right">Actions</CRMTableHeaderCell>
              </CRMTableRow>
            </CRMTableHeader>
            <CRMTableBody>
              <RoleTableRows
                roles={paginatedRoles}
                canManageRoles={canManageRoles}
                currentUserRole={currentUserRole}
                getRoleColor={getRoleColor}
                onViewRole={handleOpenView}
                onEditRole={handleOpenEdit}
                onDeleteRole={handleOpenDelete}
              />
            </CRMTableBody>
          </DataTable>
        </div>

        <CRMPagination
          currentPage={currentPage}
          totalPages={totalPages}
          totalItems={filteredRoles.length}
          rowsPerPage={rowsPerPage}
          onPageChange={setCurrentPage}
          onRowsPerPageChange={(size) => {
            setRowsPerPage(size);
            setCurrentPage(1);
          }}
          itemName="Roles"
          pageSizeOptions={[10, 25, 50, 100]}
        />
      </div>

      {/* ── Create / Edit Role Modal ── */}
      <RoleEditorModal
        isOpen={editorOpen}
        onOpenChange={setEditorOpen}
        editingRole={editingRole}
        formData={formData}
        setFormData={setFormData}
        isFormDirty={isFormDirty}
        isPending={saveRoleMutation.isPending}
        onSave={handleSaveEditor}
      />

      {/* ── View Role Details Modal ── */}
      <RoleDetailsDialog
        isOpen={viewDialogOpen}
        onOpenChange={setViewDialogOpen}
        role={viewingRole}
        roleColor={getRoleColor(viewingRole)}
      />

      {/* ── Safe Delete & Reassignment Modal ── */}
      <RoleDeleteDialog
        isOpen={deleteDialogOpen}
        onOpenChange={setDeleteDialogOpen}
        deletingRole={deletingRole}
        replacementRoleId={replacementRoleId}
        setReplacementRoleId={setReplacementRoleId}
        availableReplacementRoles={availableReplacementRoles}
        isPending={deleteRoleMutation.isPending}
        onConfirmDelete={handleDeleteConfirm}
      />
    </div>
  );
}

"use client";

import React from "react";
import { Users, User, Edit2, Trash2, Shield } from "lucide-react";
import { Badge } from "@/shared/ui/badge";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/ui/tooltip";
import {
  CRMTableRow,
  CRMTableCell,
  TruncatedText,
  CRMActionMenu,
} from "@/shared/components/crm";
import { EmptyState } from "@/shared/components/EmptyState";
import { normalizeToModuleTitle } from "@/shared/lib/auth/rbac";
import { toast } from "sonner";

interface RoleTableRowsProps {
  roles: any[];
  canManageRoles: boolean;
  currentUserRole: string;
  getRoleColor: (role: any) => string;
  onViewRole: (role: any) => void;
  onEditRole: (role: any) => void;
  onDeleteRole: (role: any) => void;
}

export function RoleTableRows({
  roles,
  canManageRoles,
  currentUserRole,
  getRoleColor,
  onViewRole,
  onEditRole,
  onDeleteRole,
}: RoleTableRowsProps) {
  if (roles.length === 0) {
    return (
      <CRMTableRow className="hover:bg-transparent border-0">
        <CRMTableCell colSpan={4} className="py-12 border-0 text-center">
          <EmptyState
            icon={Shield}
            title="No roles found"
            description="No roles match the current search query."
            className="border-0 bg-transparent shadow-none rounded-none py-6 min-h-[180px]"
          />
        </CRMTableCell>
      </CRMTableRow>
    );
  }

  return (
    <>
      {roles.map((role) => {
        const isSuperAdmin = role.name.toUpperCase() === "SUPER ADMIN";
        const isAdmin = role.name.toUpperCase() === "ADMIN";
        const canEditThis =
          canManageRoles && !(currentUserRole === "ADMIN" && isSuperAdmin);

        const rawPermissions = role.permissions || [];
        const activePermModules: string[] =
          isAdmin || isSuperAdmin
            ? ["Full Workspace Access"]
            : Array.from(
                new Set(
                  rawPermissions
                    .filter((p: any) => p.hasAccess)
                    .map(
                      (p: any) =>
                        (normalizeToModuleTitle(p.module) || p.module) as string,
                    ),
                ),
              );

        return (
          <CRMTableRow key={role.id} className="cursor-default">
            {/* Role Name */}
            <CRMTableCell>
              <div className="flex items-center gap-3 min-w-0 max-w-[220px]">
                <div
                  className="w-3 h-3 rounded-full flex-shrink-0 shadow-xs ring-2 ring-background"
                  style={{ backgroundColor: getRoleColor(role) }}
                />
                <TruncatedText
                  text={role.name}
                  lines={1}
                  onClick={() => onViewRole(role)}
                  className="font-bold text-sm tracking-tight text-foreground hover:text-primary cursor-pointer transition-colors"
                />
              </div>
            </CRMTableCell>

            {/* Assigned Users */}
            <CRMTableCell>
              <div className="flex items-center gap-2 font-medium text-sm text-foreground">
                <Users className="h-4 w-4 text-muted-foreground" />
                <span>{role._count?.users || 0}</span>
                <span className="text-xs text-muted-foreground font-normal">
                  users
                </span>
              </div>
            </CRMTableCell>

            {/* Permission Modules */}
            <CRMTableCell>
              <div className="flex flex-wrap items-center gap-1.5">
                {activePermModules.length === 0 ? (
                  <span className="text-xs text-muted-foreground italic">
                    No permissions assigned
                  </span>
                ) : (
                  <>
                    {activePermModules.slice(0, 3).map((mod) => (
                      <Badge
                        key={mod}
                        variant="secondary"
                        className="font-normal text-xs bg-muted/60 text-muted-foreground hover:bg-muted"
                      >
                        {mod}
                      </Badge>
                    ))}
                    {activePermModules.length > 3 && (
                      <TooltipProvider>
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <Badge
                              variant="outline"
                              className="font-normal text-xs border-dashed text-muted-foreground cursor-help"
                            >
                              +{activePermModules.length - 3} More
                            </Badge>
                          </TooltipTrigger>
                          <TooltipContent className="p-3 max-w-xs rounded-xl shadow-2xl">
                            <p className="text-[10px] font-bold uppercase tracking-wider opacity-70 mb-1">
                              Additional Modules ({activePermModules.length - 3})
                            </p>
                            <p className="text-xs font-medium leading-relaxed">
                              {activePermModules.slice(3).join(", ")}
                            </p>
                          </TooltipContent>
                        </Tooltip>
                      </TooltipProvider>
                    )}
                  </>
                )}
              </div>
            </CRMTableCell>

            {/* Actions */}
            <CRMTableCell className="text-right">
              <CRMActionMenu
                items={[
                  {
                    label: "View Details",
                    icon: User,
                    onClick: () => onViewRole(role),
                  },
                  ...(canEditThis
                    ? [
                        {
                          label: "Edit Permissions",
                          icon: Edit2,
                          onClick: () => onEditRole(role),
                        },
                      ]
                    : []),
                  ...(canManageRoles
                    ? [
                        {
                          label: "Delete Role",
                          icon: Trash2,
                          variant: "destructive" as const,
                          separatorBefore: true,
                          onClick: () => {
                            if (role.isSystem) {
                              toast.error(
                                `System default role "${role.name}" cannot be deleted.`,
                              );
                              return;
                            }
                            onDeleteRole(role);
                          },
                        },
                      ]
                    : []),
                ]}
              />
            </CRMTableCell>
          </CRMTableRow>
        );
      })}
    </>
  );
}

"use client";

import React, { useState, useMemo } from "react";
import {
  Shield,
  Users,
  Plus,
  Search,
  X,
  Download,
  MoreVertical,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  Trash2,
  RotateCcw,
  User,
  Edit2,
  Lock,
} from "lucide-react";
import { AppIcon } from "@/shared/components/icons/icon-registry";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Badge } from "@/shared/ui/badge";
import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/shared/ui/tooltip";
import { CRMPageContainer } from "@/shared/components/crm";
import { EmptyState } from "@/shared/components/EmptyState";
import { cn } from "@/shared/lib/utils";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/features/auth/components/auth-provider";
import client from "@/shared/lib/api/client";
import { normalizeToModuleTitle } from "@/shared/lib/auth/rbac";
import { RoleEditorModal } from "./_components/RoleEditorModal";
import { RoleDetailsDialog } from "./_components/RoleDetailsDialog";
import { RoleDeleteDialog } from "./_components/RoleDeleteDialog";
import { getRoleColor } from "./_components/RoleList";

interface RolePermission {
  module: string;
  hasAccess: boolean;
}

interface Role {
  id: string;
  name: string;
  description?: string | null;
  isSystem: boolean;
  isActive: boolean;
  color?: string | null;
  priority?: number;
  permissions: RolePermission[];
  _count?: { users: number; permissions: number; invitations?: number };
}

export default function RoleManagementPage() {
  const queryClient = useQueryClient();
  const { user, isHydrated, isAuthenticated, isInitializing } = useAuth();
  const userRoleRaw = (
    typeof user?.role === "string"
      ? user.role
      : (user?.role as any)?.name || (user as any)?.roleName || "ADMIN"
  )
    .toUpperCase()
    .replace(/[\s_-]+/g, "");

  const canManageRoles =
    !isHydrated ||
    userRoleRaw.includes("SUPERADMIN") ||
    userRoleRaw.includes("ADMIN") ||
    userRoleRaw.includes("OWNER") ||
    userRoleRaw.includes("MANAGER") ||
    userRoleRaw === "";

  // Filter & Search states
  const [typeFilter, setTypeFilter] = useState("ALL");
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: "asc" | "desc" } | null>(null);

  const setSort = (key: string, dir: "asc" | "desc" | null) => {
    setSortConfig(dir === null ? null : { key, direction: dir });
  };

  // Modals state
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<Role | null>(null);
  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [viewingRole, setViewingRole] = useState<Role | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingRole, setDeletingRole] = useState<Role | null>(null);
  const [replacementRoleId, setReplacementRoleId] = useState<string>("");

  // Editor Form State
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    color: "#3b82f6",
    permissions: [] as string[],
  });

  // Queries
  const { data: rolesData, isLoading: isRolesLoading, isPending: isRolesPending } = useQuery<{
    success: boolean;
    data: Role[];
  }>({
    queryKey: ["roles"],
    queryFn: async () => {
      const res = await client.get("/crm/roles");
      return res.data;
    },
  });

  const roles = useMemo(() => (Array.isArray(rolesData?.data) ? rolesData.data : []), [rolesData]);

  // Mutations
  const saveRoleMutation = useMutation({
    mutationFn: async ({
      roleId,
      isNew,
      payload,
    }: {
      roleId?: string;
      isNew: boolean;
      payload: any;
    }) => {
      if (isNew) {
        const res = await client.post("/crm/roles", payload);
        return res.data;
      } else {
        const res = await client.put(`/crm/roles/${roleId}`, payload);
        return res.data;
      }
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["roles"] });
      queryClient.invalidateQueries({ queryKey: ["roles-stats"] });
      toast.success(
        variables.isNew ? "Role created successfully!" : "Role updated successfully!"
      );
      setEditorOpen(false);
      setEditingRole(null);
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || "Failed to save role";
      toast.error(typeof msg === "string" ? msg : JSON.stringify(msg));
    },
  });

  const deleteRoleMutation = useMutation({
    mutationFn: async ({
      roleId,
      replacementId,
    }: {
      roleId: string;
      replacementId?: string;
    }) => {
      const query = replacementId ? `?replacementRoleId=${replacementId}` : "";
      const res = await client.delete(`/crm/roles/${roleId}${query}`);
      return res.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["roles"] });
      queryClient.invalidateQueries({ queryKey: ["roles-stats"] });
      toast.success("Role deleted successfully!");
      setDeleteDialogOpen(false);
      setDeletingRole(null);
      setReplacementRoleId("");
    },
    onError: (err: any) => {
      const msg = err.response?.data?.message || "Failed to delete role";
      toast.error(typeof msg === "string" ? msg : JSON.stringify(msg));
    },
  });

  // Handlers
  const handleOpenCreate = () => {
    setEditingRole(null);
    setFormData({
      name: "",
      description: "",
      color: "#3b82f6",
      permissions: [],
    });
    setEditorOpen(true);
  };

  const handleOpenEdit = (role: Role) => {
    setEditingRole(role);
    const activePerms = (role.permissions || [])
      .filter((p) => p.hasAccess)
      .map((p) => p.module);
    setFormData({
      name: role.name,
      description: role.description || "",
      color: role.color || getRoleColor(role),
      permissions: activePerms,
    });
    setEditorOpen(true);
  };

  const handleOpenView = (role: Role) => {
    setViewingRole(role);
    setViewDialogOpen(true);
  };

  const handleOpenDelete = (role: Role) => {
    if (role.isSystem) {
      toast.error(`System default role "${role.name}" cannot be deleted.`);
      return;
    }
    setDeletingRole(role);
    setReplacementRoleId("");
    setDeleteDialogOpen(true);
  };

  const handleSaveEditor = () => {
    if (!formData.name.trim()) {
      toast.error("Please enter a role name");
      return;
    }

    const payload = {
      name: formData.name.trim(),
      description: formData.description?.trim() || null,
      color: formData.color,
      permissions: formData.permissions,
    };

    saveRoleMutation.mutate({
      roleId: editingRole?.id,
      isNew: !editingRole,
      payload,
    });
  };

  const handleDeleteConfirm = () => {
    if (!deletingRole) return;
    deleteRoleMutation.mutate({
      roleId: deletingRole.id,
      replacementId: replacementRoleId || undefined,
    });
  };

  const isFormDirty = useMemo(() => {
    if (!editingRole) return true;
    if (formData.name !== editingRole.name) return true;
    if ((formData.color || "") !== (editingRole.color || "#3b82f6")) return true;
    const initialPerms = (editingRole.permissions || [])
      .filter((p) => p.hasAccess)
      .map((p) => p.module);
    if (formData.permissions.length !== initialPerms.length) return true;
    const currentSet = new Set(formData.permissions);
    return !initialPerms.every((p) => currentSet.has(p));
  }, [formData, editingRole]);

  const availableReplacementRoles = useMemo(() => {
    if (!deletingRole) return [];
    return roles.filter((r) => r.id !== deletingRole.id);
  }, [roles, deletingRole]);

  const hasActiveFilters = typeFilter !== "ALL" || search.trim().length > 0;

  const handleClearFilters = () => {
    setTypeFilter("ALL");
    setSearch("");
    setCurrentPage(1);
  };

  const exportCSV = () => {
    if (roles.length === 0) {
      toast.error("No roles available to export.");
      return;
    }
    const headers = ["Role Name", "Type", "Assigned Users", "Description"];
    const rows = roles.map((r: Role) => [
      `"${r.name.replace(/"/g, '""')}"`,
      r.isSystem ? "System" : "Custom",
      r._count?.users || 0,
      `"${(r.description || "").replace(/"/g, '""')}"`,
    ]);
    const csvContent =
      "data:text/csv;charset=utf-8," +
      [headers.join(","), ...rows.map((row: (string | number)[]) => row.join(","))].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `clixpro_roles_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Filter and sort logic
  const filteredRoles = useMemo(() => {
    return roles.filter((role: Role) => {
      const q = search.trim().toLowerCase();
      const matchSearch =
        q === "" ||
        role.name.toLowerCase().includes(q) ||
        (role.description && role.description.toLowerCase().includes(q));

      const matchType =
        typeFilter === "ALL" ||
        (typeFilter === "SYSTEM" && role.isSystem) ||
        (typeFilter === "CUSTOM" && !role.isSystem);

      return matchSearch && matchType;
    }).sort((a, b) => {
      if (!sortConfig) return 0;
      const dir = sortConfig.direction === "asc" ? 1 : -1;

      if (sortConfig.key === "name") {
        return a.name.localeCompare(b.name) * dir;
      }
      if (sortConfig.key === "users") {
        return ((a._count?.users || 0) - (b._count?.users || 0)) * dir;
      }
      return 0;
    });
  }, [roles, search, typeFilter, sortConfig]);

  const totalPages = Math.max(1, Math.ceil(filteredRoles.length / rowsPerPage));
  const paginatedRoles = filteredRoles.slice(
    (currentPage - 1) * rowsPerPage,
    currentPage * rowsPerPage
  );

  const isInitialLoading =
    !rolesData && (isRolesLoading || isRolesPending || !isHydrated || !isAuthenticated || isInitializing);

  return (
    <CRMPageContainer twoStageScroll>
      {/* 1. Header Layout */}
      <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
        <div className="flex items-center gap-3">
          <div
            data-animate-target="true"
            className="group h-10 w-10 rounded-xl bg-card border border-border/80 flex items-center justify-center text-muted-foreground shadow-xs shrink-0 hover:border-primary/40 hover:bg-muted/30 transition-all cursor-pointer select-none"
          >
            <AppIcon
              name="shield"
              icon={Shield}
              size={18}
