                          >
                            <DropdownMenuItem
                              onClick={() => handleOpenView(role)}
                              className="group cursor-pointer text-xs rounded-lg py-2 px-2.5 font-medium flex items-center gap-2 hover:bg-muted focus:bg-muted"
                            >
