                          <span
                            className={cn(
                              "text-xs font-bold w-14 text-left",
                              mod.isEnabled
                                ? "text-emerald-600 dark:text-emerald-400"
                                : "text-muted-foreground"
                            )}
                          >
                            {mod.isEnabled ? "Active" : "Inactive"}
                          </span>
                        </div>
                      </td>

                      {/* ACTIONS */}
                      <td className="px-4 py-3.5 text-right">
