                              variant: mod.isSystem ? ("default" as const) : ("destructive" as const),
                              disabled: mod.isSystem,
                              separatorBefore: true,
                              onClick: () => !mod.isSystem && setModuleToDelete(mod),
                            },
                          ]}
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
