"use client";

import { useEffect, useState, useCallback, useMemo } from "react";
import Link from "next/link";
import {
  Building2,
  Users,
  ShieldAlert,
  TrendingUp,
  ArrowUpRight,
  Plus,
  Zap,
  Sparkles,
  Clock,
  Target,
  Layers,
  Lock,
  RefreshCw,
  AlertTriangle,
  CreditCard,
  Activity,
  CheckCircle2,
  Server,
  IndianRupee,
