                  <span className="text-[9px] font-bold tracking-widest uppercase px-2 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-600">
                    Security Policy
                  </span>
                </div>
                <p className="text-xs text-muted-foreground leading-relaxed">
