                    {editingPlan.pricingMode === "FIXED" ? (
                      <div className="grid grid-cols-2 gap-4 pt-2">
                        <div className="space-y-1.5">
                          <Label className="text-xs font-semibold">
                            Monthly Price ({editingPlan.currency})
                          </Label>
                          <Input
                            type="number"
