                      <div>
                        <p className="text-xs font-bold text-foreground">
                          AI Features Enabled
                        </p>
                        <p className="text-[11px] text-muted-foreground">
                          Enables AI Copilot, summary, RAG, and predictive lead scoring for this tier.
                        </p>
                      </div>
