"use client";

import React, { useState, useEffect } from "react";
import {
  ContextualSettingsDrawer,
  ContextualSettingSection,
} from "@/shared/components/crm/ContextualSettingsDrawer";
import {
  SettingsSection,
  SettingsToggleRow,
  SettingsField,
} from "@/shared/components/crm/ContextualSettingsComponents";
import { Textarea } from "@/shared/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/ui/select";
import { toast } from "sonner";
import {
  Sparkles,
  Brain,
  Sliders,
  MessageSquareCode,
} from "lucide-react";
import { useAiSettings, useUpdateAiSettings } from "@/shared/hooks/use-settings";

export interface AIContextualSettingsProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  defaultSection?: string;
}

export function AIContextualSettings({
  open,
  onOpenChange,
  defaultSection = "features",
}: AIContextualSettingsProps) {
  const { data: aiData } = useAiSettings();
  const mutation = useUpdateAiSettings();

  // Feature toggles
  const [smartReply, setSmartReply] = useState(true);
  const [leadScoring, setLeadScoring] = useState(true);
  const [dealWinRate, setDealWinRate] = useState(true);
  const [sentimentAnalysis, setSentimentAnalysis] = useState(true);
  const [meetingSummarizer, setMeetingSummarizer] = useState(true);

  // Model & Reasoning Preferences
  const [defaultModel, setDefaultModel] = useState("gemini-2.5-flash");
  const [creativityLevel, setCreativityLevel] = useState("balanced");
  const [responseLength, setResponseLength] = useState("concise");

  // Context & Persona
  const [systemPrompt, setSystemPrompt] = useState(
    "You are ClixPro AI, an expert enterprise CRM sales advisor. Provide actionable, concise recommendations on deals, leads, and customer interactions."
  );
  const [autoInjectCrmContext, setAutoInjectCrmContext] = useState(true);
  const [enableActionConfirmations, setEnableActionConfirmations] = useState(true);

  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    if (aiData?.features) {
      const getFeat = (id: string, def = true) => {
        const found = aiData.features.find((f: any) => f.id === id);
        return found ? found.enabled : def;
      };
      setSmartReply(getFeat("smart_reply", true));
      setLeadScoring(getFeat("lead_scoring", true));
      setDealWinRate(getFeat("deal_win_rate", true));
      setSentimentAnalysis(getFeat("sentiment_analysis", true));
      setMeetingSummarizer(getFeat("meeting_summarizer", true));
    }
  }, [aiData]);

  const handleSave = async () => {
    try {
      const updatedFeatures = [
        {
          id: "smart_reply",
          label: "Smart Reply Suggestions",
          description: "Generate instant contextual email and message responses for customer inquiries.",
          enabled: smartReply,
        },
        {
          id: "lead_scoring",
          label: "Predictive Lead Scoring",
          description: "Automatically evaluate lead conversion likelihood based on engagement and demographic signals.",
          enabled: leadScoring,
        },
        {
          id: "deal_win_rate",
          label: "Deal Win Probability",
          description: "Analyze opportunity stage velocity and calculate win probability percentages.",
          enabled: dealWinRate,
        },
        {
          id: "sentiment_analysis",
          label: "Customer Sentiment Analysis",
          description: "Analyze tone of communications to flag at-risk accounts or high-intent buyers.",
          enabled: sentimentAnalysis,
        },
        {
          id: "meeting_summarizer",
          label: "Meeting & Note Summarization",
          description: "Distill lengthy meeting notes into structured action items and follow-ups.",
          enabled: meetingSummarizer,
        },
      ];

      await mutation.mutateAsync({
        ...(aiData || {}),
        features: updatedFeatures,
      });

      setHasChanges(false);
      toast.success("AI workspace settings updated successfully");
      onOpenChange(false);
    } catch {
      toast.error("Failed to update AI settings");
    }
  };

  const sections: ContextualSettingSection[] = [
    {
      id: "features",
      label: "Intelligence Features",
      icon: Brain,
      component: (
        <div className="space-y-5">
          <SettingsSection
            title="CRM Intelligence Engines"
            description="Toggle autonomous AI capabilities and automated reasoning across your CRM workspace."
            icon={Brain}
          >
            <div className="divide-y divide-border/40">
              <SettingsToggleRow
                label="Smart Reply & Email Drafting"
                description="Generate instant contextual email and message responses for customer inquiries."
                checked={smartReply}
                onCheckedChange={(c) => {
                  setSmartReply(c);
                  setHasChanges(true);
                }}
              />
              <SettingsToggleRow
                label="Predictive Lead Scoring"
                description="Automatically evaluate lead conversion likelihood based on engagement and demographic signals."
                checked={leadScoring}
                onCheckedChange={(c) => {
                  setLeadScoring(c);
                  setHasChanges(true);
                }}
              />
              <SettingsToggleRow
                label="Deal Win-Rate Probability Estimator"
                description="Analyze opportunity stage velocity and calculate win probability percentages."
                checked={dealWinRate}
                onCheckedChange={(c) => {
                  setDealWinRate(c);
                  setHasChanges(true);
                }}
              />
              <SettingsToggleRow
                label="Customer Sentiment & Urgency Detection"
                description="Analyze tone of communications to flag at-risk accounts or high-intent buyers."
                checked={sentimentAnalysis}
                onCheckedChange={(c) => {
                  setSentimentAnalysis(c);
                  setHasChanges(true);
                }}
              />
              <SettingsToggleRow
                label="AI Call & Meeting Summarizer"
                description="Distill lengthy meeting notes into structured action items and follow-ups."
                checked={meetingSummarizer}
                onCheckedChange={(c) => {
                  setMeetingSummarizer(c);
                  setHasChanges(true);
                }}
              />
            </div>
          </SettingsSection>
        </div>
      ),
    },
    {
      id: "reasoning",
      label: "Model & Tone Preferences",
      icon: Sliders,
      component: (
        <div className="space-y-5">
          <SettingsSection
            title="Reasoning Engine & Tone Parameters"
            description="Configure the default foundation model and communication style for assistant responses."
            icon={Sliders}
          >
            <div className="space-y-4">
              <SettingsField label="Default Reasoning Engine">
                <Select
                  value={defaultModel}
                  onValueChange={(val) => {
                    setDefaultModel(val);
                    setHasChanges(true);
                  }}
                >
                  <SelectTrigger className="h-9 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="gemini-2.5-flash">Gemini 2.5 Flash (Fast & Real-Time)</SelectItem>
                    <SelectItem value="gemini-2.5-pro">Gemini 2.5 Pro (Deep Reasoning)</SelectItem>
                    <SelectItem value="claude-3.7-sonnet">Claude 3.7 Sonnet (Advanced Coding & Analysis)</SelectItem>
                    <SelectItem value="gpt-4o">GPT-4o Omnichannel</SelectItem>
                  </SelectContent>
                </Select>
              </SettingsField>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <SettingsField label="Creativity / Temperature">
                  <Select
                    value={creativityLevel}
                    onValueChange={(val) => {
                      setCreativityLevel(val);
                      setHasChanges(true);
                    }}
                  >
                    <SelectTrigger className="h-9 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="analytical">Strict & Analytical (Temperature 0.2)</SelectItem>
                      <SelectItem value="balanced">Balanced Professional (Temperature 0.7)</SelectItem>
                      <SelectItem value="creative">Creative & Brainstorming (Temperature 1.0)</SelectItem>
                    </SelectContent>
                  </Select>
                </SettingsField>

                <SettingsField label="Response Brevity">
                  <Select
                    value={responseLength}
                    onValueChange={(val) => {
                      setResponseLength(val);
                      setHasChanges(true);
                    }}
                  >
                    <SelectTrigger className="h-9 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="concise">Concise & Direct (Executive Summary)</SelectItem>
                      <SelectItem value="detailed">Detailed & Step-by-Step Breakdown</SelectItem>
                    </SelectContent>
                  </Select>
                </SettingsField>
              </div>
            </div>
          </SettingsSection>
        </div>
      ),
    },
    {
      id: "persona",
      label: "Custom Persona & Guardrails",
      icon: MessageSquareCode,
      component: (
        <div className="space-y-5">
          <SettingsSection
            title="System Instructions & Context Injection"
            description="Customize how the AI assistant interprets your business domain and CRM data."
            icon={MessageSquareCode}
          >
            <div className="space-y-4">
              <SettingsField label="Workspace Custom System Instructions">
                <Textarea
                  value={systemPrompt}
                  onChange={(e) => {
                    setSystemPrompt(e.target.value);
                    setHasChanges(true);
                  }}
                  rows={4}
                  className="text-xs resize-none"
                  placeholder="Define custom persona guidelines, brand tone, or industry terminology..."
                />
              </SettingsField>

              <div className="divide-y divide-border/40 pt-2">
                <SettingsToggleRow
                  label="Auto-Inject Active CRM Record Context"
                  description="When viewing a contact, deal, or invoice, automatically ground AI answers with record data."
                  checked={autoInjectCrmContext}
                  onCheckedChange={(c) => {
                    setAutoInjectCrmContext(c);
                    setHasChanges(true);
                  }}
                />
                <SettingsToggleRow
                  label="Require Confirmation Before CRM Mutations"
                  description="Show interactive confirmation card before AI creates or deletes CRM records."
                  checked={enableActionConfirmations}
                  onCheckedChange={(c) => {
                    setEnableActionConfirmations(c);
                    setHasChanges(true);
                  }}
                />
              </div>
            </div>
          </SettingsSection>
        </div>
      ),
    },
  ];

  return (
    <ContextualSettingsDrawer
      open={open}
      onOpenChange={onOpenChange}
      title="AI Workspace Settings"
      subtitle="Configure CRM intelligence feature toggles, reasoning models, tone parameters, and custom personas."
      icon={Sparkles}
      badge="AI Intelligence"
      sections={sections}
      defaultSection={defaultSection}
      isSaving={mutation.isPending}
      hasUnsavedChanges={hasChanges}
      onSave={handleSave}
    />
  );
}

'use client';

import React, { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import {
  AlertCircle,
  CheckCircle2,
  Copy,
  Check,
  ShieldAlert,
  Sparkles,
} from 'lucide-react';
import { UIMessage } from '@ai-sdk/react';
import { toast } from 'sonner';
import { Button } from '@/shared/ui/button';

interface AIMessageItemProps {
  message: UIMessage & { id: string; toolInvocations?: any[] };
  onConfirmAction?: (prompt: string) => void;
  isLast?: boolean;
}

function getToolStatusLabel(toolName?: string): string {
  if (!toolName || toolName === 'unknown') return 'ClixPro AI is thinking...';
  const name = toolName.replace(/^tool-/, '').toLowerCase();
  if (name.includes('platformoverview') || name.includes('platform_overview')) return 'Gathering platform-wide telemetry & tenant stats...';
  if (name.includes('platformanalytics') || name.includes('platform_analytics') || name.includes('mrr')) return 'Calculating MRR, ARR, and financial growth analytics...';
  if (name.includes('platformorganization') || name.includes('platform_organization')) return 'Scanning multi-tenant fleet and organizations...';
  if (name.includes('platformsecurity') || name.includes('platform_security')) return 'Performing SecOps threat triage & telemetry check...';
  if (name.includes('platformaudit') || name.includes('platform_audit')) return 'Auditing platform security logs and administrative events...';
  if (name.includes('platformai') || name.includes('platform_ai')) return 'Analyzing AI ecosystem, token burn rates, and quotas...';
  if (name.includes('diagnosis') || name.includes('deep')) return 'Running comprehensive multi-dimensional platform diagnosis...';
  if (name.includes('lead')) return 'Searching CRM leads...';
  if (name.includes('customer')) return 'Looking up customer accounts...';
  if (name.includes('deal') || name.includes('pipeline')) return 'Analyzing sales pipeline...';
  if (name.includes('task') || name.includes('activity')) return 'Checking tasks & activities...';
  if (name.includes('report') || name.includes('sales')) return 'Compiling sales report analytics...';
  if (name.includes('quotation')) return 'Retrieving quotations & proposals...';
  return 'Processing CRM intelligence request...';
}

export function AIMessageItem({ message, onConfirmAction }: AIMessageItemProps) {
  const [copied, setCopied] = useState(false);
  const isUser = message.role === 'user';

  // Extract content
  const content =
    (message as any).content ||
    (message.parts?.find((p: any) => p.type === 'text') as any)?.text ||
    '';
  const isError = message.role === 'system' && content.includes('Error:');

  // Compatibility for tool invocations
  const toolInvocations =
    message.toolInvocations ||
    message.parts
      ?.filter(
        (p: any) =>
          p.type === 'tool-invocation' ||
          p.type?.startsWith('tool-') ||
          p.type === 'dynamic-tool'
      )
      .map((p: any) => ({
        toolName:
          p.toolName ||
          (p.type?.startsWith('tool-') ? p.type.replace('tool-', '') : 'unknown'),
        hasResult:
          'output' in p ||
          'result' in p ||
          p.state === 'output-available' ||
          p.state === 'output-error',
        result: p.output || p.result,
        ...p,
      })) ||
    [];

  const activeTool = toolInvocations.find((t: any) => !t.hasResult);
  const loadingStatusText = getToolStatusLabel(
    activeTool?.toolName || toolInvocations[0]?.toolName
  );

  // Check if any tool output requested confirmation
  const confirmationReq = toolInvocations.find(
    (t: any) => t.result && t.result.confirmationRequired === true
  );

  const handleCopyText = async () => {
    try {
      await navigator.clipboard.writeText(content);
      setCopied(true);
      toast.success('Copied to clipboard');
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error('Failed to copy');
    }
  };

  if (isUser) {
    return (
      <div className="flex justify-end mb-6 group animate-in fade-in duration-200">
        <div className="flex items-start gap-2.5 max-w-[85%] sm:max-w-[75%]">
          <div className="bg-primary text-primary-foreground rounded-2xl rounded-tr-xs px-4 py-3 shadow-xs">
            <div className="whitespace-pre-wrap text-xs sm:text-sm leading-relaxed">
              {content}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex justify-start mb-6 group animate-in fade-in duration-200">
      <div className="flex gap-3 max-w-full sm:max-w-[92%] w-full">
        {/* Avatar */}
        <div className="shrink-0 mt-0.5">
          <div
            className={`w-7 h-7 rounded-lg flex items-center justify-center ${
              isError
                ? 'bg-destructive/10 text-destructive'
                : 'bg-primary/10 text-primary border border-primary/20'
            } shadow-2xs`}
          >
            {isError ? <AlertCircle className="w-4 h-4" /> : <Sparkles className="w-3.5 h-3.5" />}
          </div>
        </div>

        {/* Content Box */}
        <div className="flex flex-col gap-2 min-w-0 flex-1">
          {/* AI Header Line */}
          <div className="flex items-center justify-between gap-2">
            <span className="text-[11px] font-semibold text-foreground/90 font-display">
              ClixPro AI
            </span>
            {content && !isError && (
              <button
                onClick={handleCopyText}
                className="opacity-0 group-hover:opacity-100 p-1 text-muted-foreground hover:text-foreground transition-opacity"
                title="Copy response"
              >
                {copied ? <Check className="w-3 h-3 text-primary" /> : <Copy className="w-3 h-3" />}
              </button>
            )}
          </div>

          {/* Body */}
          <div
            className={`rounded-2xl rounded-tl-xs p-4 text-xs sm:text-sm leading-relaxed overflow-hidden border ${
              isError
                ? 'border-destructive/30 bg-destructive/5 text-destructive'
                : 'border-border/60 bg-card/60 shadow-2xs'
            }`}
          >
            {isError ? (
              <div className="font-medium text-destructive">{content}</div>
            ) : content ? (
              <div className="prose prose-slate dark:prose-invert max-w-none text-xs sm:text-sm prose-p:leading-relaxed prose-p:mb-3 prose-headings:font-display prose-headings:font-bold prose-headings:text-foreground prose-table:border-collapse prose-table:w-full prose-th:bg-muted/50 prose-th:p-2 prose-th:text-left prose-th:text-xs prose-th:font-semibold prose-th:border prose-th:border-border/80 prose-td:p-2 prose-td:text-xs prose-td:border prose-td:border-border/60 prose-tr:hover:bg-muted/30 prose-code:bg-muted prose-code:px-1 prose-code:py-0.5 prose-code:rounded prose-code:text-[11px] prose-pre:bg-muted/80 prose-pre:border prose-pre:border-border prose-pre:p-3 prose-pre:rounded-xl">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{content}</ReactMarkdown>
              </div>
            ) : (
              /* Loading Tool Invocation Status */
              <div className="flex items-center gap-2.5 py-1 text-muted-foreground">
                <div className="flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-primary animate-bounce [animation-delay:-0.3s]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-primary animate-bounce [animation-delay:-0.15s]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-primary animate-bounce" />
                </div>
                <span className="text-xs font-medium text-muted-foreground animate-pulse">
                  {loadingStatusText}
                </span>
              </div>
            )}

            {/* Mutation Confirmation Card if write operation requires confirmation */}
            {confirmationReq && onConfirmAction && (
              <div className="mt-4 p-4 rounded-xl bg-amber-500/10 border border-amber-500/30 space-y-3 animate-in fade-in duration-150">
                <div className="flex items-center gap-2 text-amber-600 dark:text-amber-400 font-semibold text-xs">
                  <ShieldAlert className="w-4 h-4" />
                  <span>Action Confirmation Required</span>
                </div>
                <p className="text-xs text-foreground/80 leading-relaxed">
                  {confirmationReq.result.message ||
                    'ClixPro AI requires your confirmation before updating records in the CRM database.'}
                </p>

                {confirmationReq.result.proposedData && (
                  <div className="bg-background/80 p-2.5 rounded-lg border border-border/80 text-[11px] font-mono space-y-1">
                    {Object.entries(confirmationReq.result.proposedData).map(
                      ([key, val]) => (
                        <div key={key} className="flex justify-between">
                          <span className="text-muted-foreground uppercase">{key}:</span>
                          <span className="font-semibold text-foreground">{String(val)}</span>
                        </div>
                      )
                    )}
                  </div>
                )}

                <div className="flex items-center gap-2 pt-1">
                  <Button
                    size="sm"
                    onClick={() =>
                      onConfirmAction(
                        `Confirmed. Please execute the ${
                          confirmationReq.toolName || 'CRM'
                        } operation now.`
                      )
                    }
                    className="bg-primary text-primary-foreground text-xs font-medium h-8 rounded-lg"
                  >
                    <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" />
                    Confirm & Execute
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() =>
                      onConfirmAction('Cancel this action. Do not make changes.')
                    }
                    className="text-xs h-8 rounded-lg"
                  >
                    Cancel
                  </Button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

