];

const DEFAULT_ACCOUNT_TYPES = [
  "Customer",
  "Prospect",
  "Partner",
  "Vendor",
  "Distributor",
];

interface CustomField {
  id: string;
  name: string;
  type: "text" | "number" | "url" | "select" | "date" | "boolean" | "currency";
  required: boolean;
  options?: string;
}

interface StandardFieldConfig {
