                              >
                                <AppIcon
                                  name="trash"
                                  icon={Trash2}
                                  size={14}
                                  className="w-3.5 h-3.5 text-destructive shrink-0"
                                />
                                <span>Delete Ticket</span>
                              </DropdownMenuItem>
                            </>
                          )}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </td>
                  </tr>
                );
