                      className="border-none bg-transparent shadow-none p-0 min-h-0"
                      action={
                        hasActiveFilters
                          ? {
                              label: "Clear Filters",
                              onClick: handleClearFilters,
                              icon: RotateCcw,
                            }
                          : onNewTicketClick
                          ? {
                              label: "Submit a Ticket",
                              onClick: onNewTicketClick,
                              icon: Plus,
                            }
                          : undefined
                      }
                    />
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

