              </Button>

              <Button
                variant="outline"
                size="icon"
                disabled={currentPage <= 1}
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                className="group h-8 w-8 rounded-lg border-border/60 cursor-pointer disabled:opacity-40"
                title="Previous page"
                aria-label="Previous page"
