                  </TabsContent>

                  {/* TAB 3: Activity Timeline */}
                  <TabsContent value="timeline" className="mt-0 space-y-4">
                    <div>
                      <h3 className="text-sm font-bold text-foreground">Invoice Timeline</h3>
                      <p className="text-xs text-muted-foreground">Audit trail and life cycle events for this invoice</p>
                    </div>

                    {!invoice.timelineEvents || invoice.timelineEvents.length === 0 ? (
                      <EmptyState
                        title="No timeline events recorded"
                        description="Timeline events will be logged as actions occur on this invoice."
                        icon={Clock}
                        className="border border-dashed border-border/80 rounded-2xl bg-muted/10 py-10"
                      />
                    ) : (
                      <div className="relative pl-6 space-y-6 before:absolute before:left-2.5 before:top-2 before:bottom-2 before:w-0.5 before:bg-border/60">
                        {invoice.timelineEvents.map((evt: any) => (
                          <div key={evt.id} className="relative group">
                            <div className="absolute -left-6 top-0.5 size-3 rounded-full bg-primary ring-4 ring-background" />
                            <div className="text-xs font-semibold text-foreground">{evt.description || evt.action}</div>
                            <div className="text-[11px] text-muted-foreground mt-0.5">
                              {new Date(evt.createdAt).toLocaleString("en-IN", {
                                month: "short",
                                day: "numeric",
                                year: "numeric",
                                hour: "2-digit",
                                minute: "2-digit",
                              })}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </TabsContent>
                </>
              )}
            </div>
          </Tabs>

          {/* Footer Actions */}
          <DialogFooter className="shrink-0 -mx-0 -mb-0 px-6 py-3.5 border-t border-border/80 bg-muted/30 flex items-center justify-between sm:justify-between flex-row">
            <Button
              variant="ghost"
              size="sm"
              onClick={onRequestDeleteInvoice}
              disabled={isDeletingInvoice || (invoice?.payments && invoice.payments.length > 0)}
              className="text-xs text-destructive hover:bg-destructive/10 hover:text-destructive gap-1.5 font-semibold h-8"
            >
              <AppIcon name="trash" size={14} className="text-destructive" /> Delete Invoice
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={onClose}
              className="text-xs font-semibold h-8"
            >
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Invoice Confirmation Dialog */}
      <AlertDialog open={isDeleteInvoiceOpen} onOpenChange={setIsDeleteInvoiceOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Invoice</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete invoice {invoice?.invoiceNumber}? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeletingInvoice}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={handleConfirmDeleteInvoice}
              disabled={isDeletingInvoice}
            >
              {isDeletingInvoice ? "Deleting..." : "Delete Invoice"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Delete Payment Confirmation Dialog */}
      <AlertDialog
        open={Boolean(paymentToDelete)}
        onOpenChange={(open) => {
          if (!open) setPaymentToDelete(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Payment</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this payment record{paymentToDelete?.paymentNumber ? ` (${paymentToDelete.paymentNumber})` : ""}? Outstanding balance will be restored.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeletingPayment}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={handleConfirmDeletePayment}
              disabled={isDeletingPayment}
            >
              {isDeletingPayment ? "Deleting..." : "Delete Payment"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Record Payment Sub-Modal */}
      {invoice && (
        <RecordPaymentModal
          isOpen={isRecordPaymentOpen}
          onClose={() => {
            setIsRecordPaymentOpen(false);
            refetch();
          }}
          invoice={{
            id: invoice.id,
            invoiceNumber: invoice.invoiceNumber,
            totalAmount: invoice.totalAmount,
            paidAmount: invoice.paidAmount,
            balanceAmount: invoice.balanceAmount,
            currency: curr,
            customer: invoice.customer,
          }}
        />
      )}
    </>
  );
}

