                  {/* Paid Amount */}
                  <CRMTableCell className="px-4 py-3.5">
                    <span className="font-semibold text-emerald-600 dark:text-emerald-400 text-xs font-mono">
                      {inv.paidAmount > 0
                        ? formatCurrency(inv.paidAmount, inv.currency)
