                  label="Enable quotation approval workflow"
                  description="Require manager review and sign-off before quotations can be published or dispatched to clients."
                  checked={enableApprovalWorkflow}
                  onCheckedChange={(c) => {
                    setEnableApprovalWorkflow(c);
                    setHasChanges(true);
                  }}
                />

                {enableApprovalWorkflow && (
                  <>
                    <SettingsToggleRow
                      label="Require approval for excessive discounts"
                      description="Require manager approval when a quotation exceeds the allowed discount threshold."
                      checked={requireApprovalForExcessiveDiscounts}
                      onCheckedChange={(c) => {
                        setRequireApprovalForExcessiveDiscounts(c);
                        setHasChanges(true);
                      }}
                    />

                    {requireApprovalForExcessiveDiscounts && (
                      <div className="py-2.5 px-2 -mx-2 bg-muted/20 rounded-md">
                        <SettingsField
                          label="Maximum discount allowed without approval (%)"
                          description="Discounts exceeding this threshold will automatically flag the quote for manager authorization."
                          required
                        >
                          <div className="relative max-w-xs">
                            <Input
                              type="number"
                              min="0"
                              max="100"
                              value={maxDiscountWithoutApproval}
                              onChange={(e) => {
                                setMaxDiscountWithoutApproval(e.target.value);
                                setHasChanges(true);
                              }}
                              className={`h-9 text-xs pr-7 font-mono ${
                                errors.maxDiscountWithoutApproval ? "border-destructive focus-visible:ring-destructive" : ""
                              }`}
                            />
                            <span className="absolute right-2.5 top-2.5 text-xs text-muted-foreground pointer-events-none">
                              %
                            </span>
                          </div>
                          {errors.maxDiscountWithoutApproval && (
                            <p className="text-[11px] text-destructive flex items-center gap-1 mt-1 font-medium">
                              <AlertCircle className="w-3 h-3 shrink-0" />
                              {errors.maxDiscountWithoutApproval}
                            </p>
                          )}
                        </SettingsField>
                      </div>
                    )}

                    <SettingsToggleRow
                      label="Require approval for high-value quotations"
                      description="Require executive sign-off for quotations exceeding a predefined financial amount threshold."
                      checked={requireHighValueApproval}
                      onCheckedChange={(c) => {
                        setRequireHighValueApproval(c);
                        setHasChanges(true);
                      }}
                    />

                    {requireHighValueApproval && (
                      <div className="py-2.5 px-2 -mx-2 bg-muted/20 rounded-md">
                        <SettingsField
                          label="High-Value Quotation Threshold Amount"
                          description="Quotations with total contract value above this figure will mandate executive approval."
                          required
                        >
                          <div className="relative max-w-xs">
                            <Input
                              type="number"
                              min="1"
                              value={highValueThreshold}
                              onChange={(e) => {
                                setHighValueThreshold(e.target.value);
                                setHasChanges(true);
                              }}
                              className={`h-9 text-xs pr-12 font-mono ${
                                errors.highValueThreshold ? "border-destructive focus-visible:ring-destructive" : ""
                              }`}
                            />
                            <span className="absolute right-2.5 top-2.5 text-xs text-muted-foreground pointer-events-none">
                              {defaultCurrency}
                            </span>
                          </div>
                          {errors.highValueThreshold && (
                            <p className="text-[11px] text-destructive flex items-center gap-1 mt-1 font-medium">
                              <AlertCircle className="w-3 h-3 shrink-0" />
                              {errors.highValueThreshold}
                            </p>
                          )}
                        </SettingsField>
                      </div>
                    )}
                  </>
                )}
              </div>
            </div>
          </SettingsSection>
        </div>
      ),
    },
  ];

  return (
    <ContextualSettingsDrawer
      open={open}
      onOpenChange={onOpenChange}
      title="Quotation Settings"
      subtitle="Customize quotation PDF templates, automated numbering sequences, tax configurations, and terms."
      icon={FileText}
      sections={sections}
      defaultSection={defaultSection}
      isSaving={isSaving}
      hasUnsavedChanges={hasChanges}
      onSave={handleSave}
      onReset={handleResetDefaults}
    />
  );
}

import { useState, useMemo, useEffect } from "react";
import { useQuotations } from "@/shared/hooks/use-crm";
import { QuotationType } from "@/shared/types/quotation";
import { toast } from "sonner";

export type QuotationSortKey = string;
export type QuotationSortDirection = "asc" | "desc";

export interface QuotationSortConfig {
  key: QuotationSortKey;
  direction: QuotationSortDirection;
}

export type QuotationStatusFilter =
  | "ALL"
  | "DRAFT"
  | "SENT"
  | "ACCEPTED"
  | "REJECTED"
  | "EXPIRED";

export interface UseQuotationsDataReturn {
  // raw
  safeQuotations: QuotationType[];
  isLoading: boolean;
  isPending: boolean;
  refetch: () => void;

  // filter/search state
  search: string;
  setSearch: (v: string) => void;
  statusFilter: QuotationStatusFilter;
  setStatusFilter: (v: QuotationStatusFilter) => void;

  // selection
  selectedQuoteIds: string[];
  setSelectedQuoteIds: React.Dispatch<React.SetStateAction<string[]>>;

  // sort state
  sortConfig: QuotationSortConfig | null;
  setSort: (key: string, dir: "asc" | "desc" | null) => void;

  // pagination state
  currentPage: number;
  setCurrentPage: React.Dispatch<React.SetStateAction<number>>;
  rowsPerPage: number;
  setRowsPerPage: (v: number) => void;

  // derived
  filteredQuotations: QuotationType[];
  paginatedQuotations: QuotationType[];
  totalPages: number;
  hasActiveFilters: boolean;

  // actions
  handleClearFilters: () => void;
  exportCSV: () => void;
}

/**
 * Encapsulates all list-data logic for the quotations page:
 *   - sources useQuotations()
 *   - search (quoteId, client, leadName)
 *   - status filtering (ALL | DRAFT | SENT | ACCEPTED | REJECTED | EXPIRED)
 *   - sorting with direction cycle (asc → desc → null)
 *   - pagination (page sizes: 10, 25, 50, 100; default: 10)
 *   - page reset when search or filter changes
 *   - row selection state
 *   - CSV export
 */
export function useQuotationsData(): UseQuotationsDataReturn {
  const { data, isLoading, isPending, refetch } = useQuotations();

  const safeQuotations = useMemo<QuotationType[]>(
    () =>
      Array.isArray(data?.quotations) ? (data.quotations as QuotationType[]) : [],
    [data]
  );

  // --- filter/search ---
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<QuotationStatusFilter>("ALL");

  // --- selection ---
  const [selectedQuoteIds, setSelectedQuoteIds] = useState<string[]>([]);

  // --- sort ---
  const [sortConfig, setSortConfig] = useState<QuotationSortConfig | null>(null);

  const setSort = (key: string, dir: "asc" | "desc" | null) => {
    setSortConfig(dir === null ? null : { key, direction: dir });
  };

  // --- pagination ---
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPageState] = useState(10);

  const setRowsPerPage = (v: number) => {
    setRowsPerPageState(v);
    setCurrentPage(1);
  };

  // Reset page when search or filter changes
  useEffect(() => {
    setCurrentPage(1);
  }, [search, statusFilter]);

  // --- derived data ---
  const filteredQuotations = useMemo(() => {
    return safeQuotations
      .filter((quote: QuotationType) => {
        const matchSearch =
          search.trim() === "" ||
          (quote.quoteId &&
            quote.quoteId.toLowerCase().includes(search.toLowerCase())) ||
          (quote.client &&
            quote.client.toLowerCase().includes(search.toLowerCase())) ||
          (quote.leadName &&
            quote.leadName.toLowerCase().includes(search.toLowerCase()));

        const matchStatus =
          statusFilter === "ALL" ||
          quote.status?.toUpperCase() === statusFilter.toUpperCase();

        return matchSearch && matchStatus;
      })
      .sort((a, b) => {
        if (!sortConfig) return 0;
        let aVal: string | number;
        let bVal: string | number;

        if (sortConfig.key === "amount") {
          aVal = a.amountValue ?? 0;
          bVal = b.amountValue ?? 0;
        } else {
          const rawA = a[sortConfig.key as keyof QuotationType];
          const rawB = b[sortConfig.key as keyof QuotationType];
          aVal = rawA ? String(rawA).toLowerCase() : "";
          bVal = rawB ? String(rawB).toLowerCase() : "";
        }

        if (aVal < bVal) return sortConfig.direction === "asc" ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === "asc" ? 1 : -1;
        return 0;
      });
  }, [safeQuotations, search, statusFilter, sortConfig]);

  const totalPages = Math.max(
    1,
    Math.ceil(filteredQuotations.length / rowsPerPage)
  );

  const paginatedQuotations = filteredQuotations.slice(
    (currentPage - 1) * rowsPerPage,
    currentPage * rowsPerPage
  );

  const hasActiveFilters = statusFilter !== "ALL" || search.trim().length > 0;

  const handleClearFilters = () => {
    setStatusFilter("ALL");
    setSearch("");
    setCurrentPage(1);
  };

  // --- CSV export ---
  const exportCSV = () => {
    if (safeQuotations.length === 0) {
      toast.error("No quotations available to export.");
      return;
    }
    const headers = [
      "Quote ID",
      "Customer",
      "Related Deal",
      "Amount",
      "Status",
      "Valid Till",
      "Created At",
    ];
    const rows = safeQuotations.map((q: QuotationType) => [
      q.quoteId || "",
      `"${(q.client || "").replace(/"/g, '""')}"`,
      `"${(q.leadName || "").replace(/"/g, '""')}"`,
      q.amountValue ?? 0,
      q.status || "DRAFT",
      q.validTill || "",
      q.lastActivity || "",
    ]);
    const csvContent =
      "data:text/csv;charset=utf-8," +
      [
        headers.join(","),
        ...rows.map((row: (string | number)[]) => row.join(",")),
      ].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute(
      "download",
      `clixpro_quotations_${new Date().toISOString().slice(0, 10)}.csv`
    );
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return {
    safeQuotations,
    isLoading,
    isPending,
    refetch,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    selectedQuoteIds,
    setSelectedQuoteIds,
    sortConfig,
    setSort,
    currentPage,
    setCurrentPage,
    rowsPerPage,
    setRowsPerPage,
    filteredQuotations,
    paginatedQuotations,
    totalPages,
    hasActiveFilters,
    handleClearFilters,
    exportCSV,
  };
}

