          >
            {updateSettingsMutation.isPending ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <AppIcon name="save" icon={Save} size={14} />
            )}
            Save Preferences
          </Button>
        </div>
      </CRMCard>
    </div>
  );
}

