"use client";

import React, { useState, useMemo } from "react";
import { Search, X } from "lucide-react";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { cn } from "@/shared/lib/utils";
import { useLeads, useCustomers, useQuotations } from "@/shared/hooks/use-crm";
import { LeadType } from "@/shared/types/lead";
import { CustomerType } from "@/shared/types/customer";
import { QuotationType } from "@/shared/types/quotation";

export type RelationType = "lead" | "customer" | "quotation";

export interface RelatedRecord {
  type: RelationType;
  id: string;
  label: string;
  sub?: string;
}

export const RECORD_TYPE_LABELS: Record<RelationType, { label: string; color: string }> = {
  lead: { label: "Lead", color: "bg-blue-500/10 text-blue-700 dark:text-blue-400" },
  customer: { label: "Customer", color: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400" },
  quotation: { label: "Quote", color: "bg-purple-500/10 text-purple-700 dark:text-purple-400" },
};

interface TaskRelatedRecordPickerProps {
  relatedRecord: RelatedRecord | null;
  onSelectRecord: (record: RelatedRecord | null) => void;
}

export function TaskRelatedRecordPicker({
  relatedRecord,
  onSelectRecord,
}: TaskRelatedRecordPickerProps) {
  const [recordSearch, setRecordSearch] = useState("");
  const [recordDropdownOpen, setRecordDropdownOpen] = useState(false);

  const { data: leadsData } = useLeads();
  const { data: customersData } = useCustomers();
  const { data: quotesData } = useQuotations();

  const leads = (leadsData?.leads || (Array.isArray(leadsData) ? leadsData : [])) as LeadType[];
  const customers = (customersData?.customers || (Array.isArray(customersData) ? customersData : [])) as CustomerType[];
  const quotes = (quotesData?.quotations || (Array.isArray(quotesData) ? quotesData : [])) as QuotationType[];

  const recordResults = useMemo(() => {
    if (!recordSearch.trim()) return [];
    const q = recordSearch.toLowerCase();
    const results: RelatedRecord[] = [];

    leads.forEach((l: LeadType) => {
      if (l.name?.toLowerCase().includes(q) || l.company?.toLowerCase().includes(q)) {
        results.push({ type: "lead", id: l.id, label: l.name, sub: l.company });
      }
    });

    customers.forEach((c: CustomerType) => {
      if (c.name?.toLowerCase().includes(q) || c.company?.toLowerCase().includes(q)) {
        results.push({ type: "customer", id: c.id, label: c.name, sub: c.company });
      }
    });

    quotes.forEach((qu: QuotationType) => {
      const title = qu.quoteId ? `#${qu.quoteId}` : "Quote";
      const clientName = qu.client || qu.leadName || qu.leadDetails?.name || "";
      if (title.toLowerCase().includes(q) || clientName.toLowerCase().includes(q)) {
        results.push({ type: "quotation", id: qu.id, label: title, sub: clientName });
      }
    });

    return results.slice(0, 10);
  }, [recordSearch, leads, customers, quotes]);

  return (
    <div className="space-y-1.5">
      <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
        Related Record
      </Label>

      {relatedRecord ? (
        <div className="h-10 rounded-lg border border-border bg-muted/10 px-3 flex items-center justify-between">
          <div className="flex items-center gap-2 min-w-0">
            <span
              className={cn(
                "text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded",
                RECORD_TYPE_LABELS[relatedRecord.type].color,
              )}
            >
              {RECORD_TYPE_LABELS[relatedRecord.type].label}
            </span>
            <span className="text-sm font-medium text-foreground truncate">
              {relatedRecord.label}
            </span>
            {relatedRecord.sub && (
              <span className="text-xs text-muted-foreground truncate">
                — {relatedRecord.sub}
              </span>
            )}
          </div>
          <button
            type="button"
            onClick={() => onSelectRecord(null)}
            aria-label="Remove related record"
            className="text-muted-foreground hover:text-destructive shrink-0"
          >
            <X className="size-3.5" />
          </button>
        </div>
      ) : (
        <div className="relative">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground pointer-events-none" />
            <Input
              placeholder="Search leads, customers, quotes..."
              value={recordSearch}
              onChange={(e) => {
                setRecordSearch(e.target.value);
                setRecordDropdownOpen(true);
              }}
              onFocus={() => setRecordDropdownOpen(true)}
              onBlur={() => setTimeout(() => setRecordDropdownOpen(false), 200)}
              className="h-10 pl-9 text-sm"
            />
          </div>

          {recordDropdownOpen && recordResults.length > 0 && (
            <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-popover border border-border rounded-lg shadow-lg max-h-52 overflow-y-auto">
              {recordResults.map((r) => (
                <button
                  key={`${r.type}-${r.id}`}
                  type="button"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => {
                    onSelectRecord(r);
                    setRecordSearch("");
                    setRecordDropdownOpen(false);
                  }}
                  className="w-full px-3 py-2.5 text-left hover:bg-muted/60 flex items-center gap-2 transition-colors first:rounded-t-lg last:rounded-b-lg"
                >
                  <span
                    className={cn(
                      "text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded shrink-0",
                      RECORD_TYPE_LABELS[r.type].color,
                    )}
                  >
                    {RECORD_TYPE_LABELS[r.type].label}
                  </span>
                  <span className="text-sm font-medium text-foreground truncate">
                    {r.label}
                  </span>
                  {r.sub && (
                    <span className="text-xs text-muted-foreground truncate ml-auto">
                      {r.sub}
                    </span>
                  )}
                </button>
              ))}
            </div>
          )}

          {recordDropdownOpen && recordSearch.trim() && recordResults.length === 0 && (
            <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-popover border border-border rounded-lg shadow-lg px-3 py-4 text-center">
              <p className="text-xs text-muted-foreground">No records found</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { tool } from 'ai';
import { z } from 'zod';

export interface McpUserContext {
  authToken: string;
  userId?: string;
  tenantId?: string;
  role?: string;
  correlationId?: string;
}

const CRM_API_BASE_URL =
  process.env.CRM_API_BASE_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  'http://localhost:4000/api';

/**
 * Sanitizes headers and scrubs sensitive tokens from error messages.
 */
function scrubError(text: string): string {
  if (!text) return 'An unexpected error occurred.';
  return text
    .replace(/eyJ[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]*/g, '[REDACTED_TOKEN]')
    .replace(/PrismaClientKnownRequestError/i, 'DatabaseError')
    .replace(/SELECT\s+.+\s+FROM/gi, '[QUERY_REDACTED]');
}

/**
 * Dispatches an authenticated HTTP request to the ClixProCRM API gateway on behalf of the user.
 */
async function callCrmApi(
  context: McpUserContext,
  endpoint: string,
  method = 'GET',
  body?: unknown,
  query?: Record<string, string | number | boolean | undefined | null>
): Promise<any> {
  const cleanBase = CRM_API_BASE_URL.replace(/\/+$/, '');
  const cleanPath = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
  const url = new URL(`${cleanBase}${cleanPath}`);

  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined && value !== null) {
        url.searchParams.set(key, String(value));
      }
    }
  }

  const headers: Record<string, string> = {
    Accept: 'application/json',
    'Content-Type': 'application/json',
  };

  if (context.authToken) {
    headers['Authorization'] = `Bearer ${context.authToken}`;
  }
  if (context.correlationId) {
    headers['X-Correlation-ID'] = context.correlationId;
    headers['X-Request-ID'] = context.correlationId;
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 10000);

  try {
    const res = await fetch(url.toString(), {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
    clearTimeout(timeoutId);

    if (!res.ok) {
      let errorMsg = `CRM API responded with status ${res.status}`;
      try {
        const errorData = await res.json();
        if (errorData?.message) {
          errorMsg = Array.isArray(errorData.message)
            ? errorData.message.join(', ')
            : String(errorData.message);
        }
      } catch {
        // Fall back to status text
      }

      if (res.status === 401) {
        return { error: 'Authentication expired or invalid. Please sign in again.' };
      }
      if (res.status === 403) {
        return { error: 'Permission denied: Your role does not allow this operation.' };
      }
      if (res.status === 404) {
        return { error: 'Resource not found in CRM.' };
      }
      if (res.status === 429) {
        return { error: 'Rate limit exceeded. Please wait a moment before trying again.' };
      }
      if (res.status >= 500) {
        return { error: 'CRM service is temporarily unavailable. Please try again shortly.' };
      }

      return { error: scrubError(errorMsg) };
    }

    const data = await res.json();
    return data?.data !== undefined ? data.data : data;
  } catch (err: any) {
    clearTimeout(timeoutId);
    if (err.name === 'AbortError') {
      return { error: 'Request to CRM service timed out. Please try again.' };
    }
    return { error: 'Could not connect to CRM backend service. Please check your network connection.' };
  }
}

