import { createBrowserClient } from '@supabase/ssr';

function parseCookies(cookieHeader: string): Array<{ name: string; value: string }> {
  if (!cookieHeader) return [];
  return cookieHeader
    .split(';')
    .map((c) => c.trim())
    .filter(Boolean)
    .map((c) => {
      const idx = c.indexOf('=');
      if (idx === -1) return { name: c, value: '' };
      return {
        name: c.slice(0, idx).trim(),
        value: c.slice(idx + 1).trim(),
      };
    });
}

function serializeCookie(name: string, value: string, options: any = {}): string {
  let cookieStr = `${name}=${value}; Path=${options.path || '/'}; SameSite=${options.sameSite || 'Lax'}`;
  if (options.secure || (typeof window !== 'undefined' && window.location.protocol === 'https:')) {
    cookieStr += '; Secure';
  }
  if (typeof options.maxAge === 'number') {
    cookieStr += `; Max-Age=${options.maxAge}`;
  }
  if (options.domain) {
    cookieStr += `; Domain=${options.domain}`;
  }
  return cookieStr;
}

function initBrowserClient() {
  return createBrowserClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          if (typeof document === 'undefined') return [];
          return parseCookies(document.cookie);
        },
        setAll(cookiesToSet) {
          if (typeof document === 'undefined') return;
          const isRemembered =
            typeof window !== 'undefined' &&
            localStorage.getItem('clixpro_remember_me') === '1';

          if (isRemembered) {
            document.cookie = serializeCookie('clixpro_remember_me', '1', {
              maxAge: 30 * 24 * 60 * 60,
              path: '/',
              sameSite: 'Lax',
            });
          } else {
            document.cookie = serializeCookie('clixpro_remember_me', '', {
              maxAge: 0,
              path: '/',
              sameSite: 'Lax',
            });
          }

          cookiesToSet.forEach(({ name, value, options }) => {
            const cookieOpts = { ...options };
            if (cookieOpts.maxAge === 0) {
              // Explicit cookie removal
              cookieOpts.maxAge = 0;
            } else if (isRemembered) {
              // 30 days persistent cookie
              cookieOpts.maxAge = 30 * 24 * 60 * 60;
            } else {
              // Session cookie (cleared when browser session ends)
              delete cookieOpts.maxAge;
              delete cookieOpts.expires;
            }
            document.cookie = serializeCookie(name, value, cookieOpts);
          });
        },
      },
    }
  );
}

let clientInstance: ReturnType<typeof initBrowserClient> | null = null;

export function createClient() {
  if (typeof window !== 'undefined' && clientInstance) {
    return clientInstance;
  }

  const client = initBrowserClient();

  if (typeof window !== 'undefined') {
    clientInstance = client;
  }

  return client;
}

"use client";

import * as React from "react";
import { ArrowUp, ArrowDown, ChevronsUpDown } from "lucide-react";
import { cn } from "@/shared/lib/utils";

export type SortDirection = "asc" | "desc" | null;

export interface DataTableColumnHeaderProps {
  title?: React.ReactNode;
  children?: React.ReactNode;
  align?: "left" | "center" | "right";
  sortable?: boolean;
  sortDirection?: SortDirection;
  onSort?: (direction: SortDirection) => void;
  className?: string;
  iconClassName?: string;
}

export function DataTableColumnHeader({
  title,
  children,
  align = "left",
  sortable = false,
  sortDirection = null,
  onSort,
  className,
  iconClassName,
}: DataTableColumnHeaderProps) {
  const content = title ?? children;

  const handleToggleSort = (e: React.MouseEvent | React.KeyboardEvent) => {
    if (!sortable || !onSort) return;
    e.stopPropagation();

    // 3-state cycling: null -> asc -> desc -> null
    if (sortDirection === "asc") {
      onSort("desc");
    } else if (sortDirection === "desc") {
      onSort(null);
    } else {
      onSort("asc");
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (sortable && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      handleToggleSort(e);
    }
  };

  const alignmentClass = 
    align === "right" 
      ? "justify-end text-right" 
      : align === "center" 
      ? "justify-center text-center" 
      : "justify-start text-left";

  if (!sortable) {
    return (
      <div
        className={cn(
          "inline-flex items-center gap-1.5 text-xs font-bold text-foreground select-none",
          alignmentClass,
          className
        )}
      >
        {typeof content === "string" ? <span>{content}</span> : content}
      </div>
    );
  }

  const isSorted = sortDirection === "asc" || sortDirection === "desc";

  return (
    <div
      role="button"
      tabIndex={0}
      aria-sort={sortDirection === "asc" ? "ascending" : sortDirection === "desc" ? "descending" : "none"}
      onClick={handleToggleSort}
      onKeyDown={handleKeyDown}
      className={cn(
        "group inline-flex items-center gap-1.5 cursor-pointer text-xs font-bold select-none transition-colors duration-150 outline-none rounded py-0.5",
        isSorted ? "text-primary font-bold" : "text-foreground hover:text-primary",
        alignmentClass,
        className
      )}
    >
      <span>{content}</span>
      <span className={cn("inline-flex shrink-0 items-center transition-colors", iconClassName)}>
        {sortDirection === "asc" ? (
          <ArrowUp className="h-3.5 w-3.5 text-primary" aria-hidden="true" />
        ) : sortDirection === "desc" ? (
          <ArrowDown className="h-3.5 w-3.5 text-primary" aria-hidden="true" />
        ) : (
          <ChevronsUpDown className="h-3.5 w-3.5 text-muted-foreground/40 group-hover:text-foreground transition-opacity" aria-hidden="true" />
        )}
      </span>
    </div>
  );
}

